export const psychologyOfTheFirstMessage: LocalizedArticle = {
  en: [
    { type: "p", text: "You matched. You typed \"hey\". And then… nothing. If this loop feels familiar, the problem probably isn't you — it's the message. First messages are one of the most heavily measured moments in online dating, and the data from millions of conversations points in one direction: greetings get ignored, questions get answers. The psychology behind that gap is worth understanding, because it changes how you start every conversation — on an app or off it." },
    { type: "h2", text: "The Data: \"Hey\" Is the Worst Opener on Every App" },
    { type: "p", text: "OkCupid's data team analyzed over 500,000 first messages on the platform and found that the most common openers — \"hi\", \"hey\", \"hello\" — had reply rates well below average, while messages that engaged with something specific did markedly better. The most generic possible message turned out to be the least effective one." },
    { type: "p", text: "Hinge ran the experiment from the other side: in 2015 the company tested around 100 different opening lines across its user base for a month. The result was the same story. The classic \"hey, what's up?\" was consistently outperformed by openers that asked a personalized question or proposed something concrete. Novelty, specificity and an actual question to answer beat a bare greeting every time." },
    { type: "h2", text: "The Harvard Finding: Asking Questions Makes People Like You" },
    { type: "p", text: "This isn't just an app-data quirk. In 2017, Karen Huang, Michael Yeomans, Alison Wood Brooks, Julia Minson and Francesca Gino published a series of studies in the Journal of Personality and Social Psychology under a memorable title: \"It Doesn't Hurt to Ask: Question-Asking Increases Liking.\" Across live conversations between strangers, people who asked more questions — especially **follow-up questions**, the ones that build on what the other person just said — were consistently better liked by their conversation partners." },
    { type: "p", text: "The most striking part came from the field: the researchers analyzed real speed-dating conversations — 110 daters, more than 2,000 dates. Speed daters who asked more follow-up questions were more likely to get a \"yes\" to a second date. The top third of question-askers received the most second-date offers. Asking wasn't just polite; it was measurably attractive." },
    { type: "h2", text: "Why It Works: A Good Question Is a Two-Way Gift" },
    { type: "p", text: "The mechanism the researchers identified is called **responsiveness**: when you ask someone a real question, you signal that you're listening, that you understand, and that you care. And answering feels genuinely good — psychologists have long known that self-disclosure, talking about yourself to an interested listener, is intrinsically enjoyable. The person answering attributes that enjoyment to you, the asker. A good question makes the other person feel interesting — and makes you more likable in the process." },
    { type: "p", text: "There's one more ingredient: turn-taking. In a 2013 study in the Journal of Experimental Social Psychology, Susan Sprecher and colleagues had strangers get acquainted either by taking turns asking and answering questions, or by having one person disclose while the other only listened. The turn-takers reported significantly more liking, closeness, perceived similarity and enjoyment. Connection doesn't come from one person performing; it comes from **alternating** — you ask, I answer, I ask, you answer." },
    { type: "h2", text: "How to Start a Conversation That Actually Gets a Reply" },
    { type: "p", text: "Put the data and the psychology together and the playbook writes itself:" },
    { type: "ul", items: [
      "**Skip the bare greeting.** \"Hey\" gives the other person nothing to answer — it outsources all the effort to them.",
      "**Ask about something specific.** Reference a detail they actually shared; specificity is proof you paid attention.",
      "**Make it open-ended.** A question that can be answered with \"yes\" or \"no\" usually will be — and the conversation dies there.",
      "**Follow up on the answer.** The single strongest signal in the research wasn't the first question but the second one — the one that shows you listened.",
    ] },
    { type: "p", text: "Here's the catch, though: on most dating apps, all of this is left to chance. The app matches you on photos, drops you into an empty chat box, and hopes you'll somehow become a skilled question-asker on your own. The science says questions and turn-taking build connection — and the design gives you a blank screen and a \"hey\"." },
    { type: "h2", accent: "green", text: "Qulo Builds the Question Into the First Contact" },
    { type: "p", text: "Qulo's core mechanic starts exactly where the research points. To match with someone on Qulo, you don't send a cold opener — you answer **2-10 questions that person wrote themselves**. Your very first contact is already an exchange of real questions and real answers about how you think and what you care about. The awkward \"what do I even say?\" moment is gone, because the conversation starts mid-substance, not at \"hey\"." },
    { type: "p", text: "To be clear: no app can promise that a great first exchange becomes a great relationship — no honest reading of the research supports that claim. What the research does support is narrower and more useful: questions, self-disclosure and turn-taking are reliably how strangers start to like each other. Qulo simply makes that dynamic the entry point instead of leaving it to luck." },
    { type: "quote", text: "The best first message was never \"hey\". It was always a question — one that shows you actually looked, and actually care about the answer." },
    { type: "h2", accent: "green", text: "Conclusion" },
    { type: "p", text: "Half a million analyzed messages say generic greetings get ignored. Harvard's conversation studies say question-askers — especially follow-up askers — are better liked and get more second dates. And experimental psychology says taking turns asking and answering is how closeness actually forms. If that's how connection starts, why leave it to a blank chat box? Qulo starts every match with questions worth answering. Download Qulo and start your next conversation where the science says it should start." },
  ],
  tr: [
    { type: "p", text: "Eşleştiniz. \"Selam\" yazdınız. Ve sonra… hiçbir şey. Bu döngü tanıdık geliyorsa sorun büyük ihtimalle sizde değil — mesajda. İlk mesaj, online dating'in en çok ölçülen anlarından biri ve milyonlarca konuşmanın verisi tek bir yönü gösteriyor: selamlaşmalar görmezden geliniyor, sorular cevap alıyor. Bu farkın arkasındaki psikolojiyi anlamaya değer; çünkü uygulamada da uygulama dışında da her sohbete nasıl başladığınızı değiştiriyor." },
    { type: "h2", text: "Veri: \"Selam\" Her Uygulamanın En Kötü Açılışı" },
    { type: "p", text: "OkCupid'in veri ekibi platformdaki 500.000'den fazla ilk mesajı analiz etti ve en yaygın açılışların — \"hi\", \"hey\", \"hello\" — yanıt oranlarının ortalamanın belirgin şekilde altında kaldığını, buna karşılık somut bir şeye değinen mesajların çok daha iyi performans gösterdiğini buldu. Akla gelebilecek en jenerik mesaj, en etkisiz mesaj çıktı." },
    { type: "p", text: "Hinge aynı deneyi diğer taraftan yaptı: şirket 2015'te yaklaşık 100 farklı açılış cümlesini bir ay boyunca kullanıcı kitlesi üzerinde test etti. Sonuç aynı hikâyeydi. Klasik \"hey, what's up?\" kişiselleştirilmiş bir soru soran ya da somut bir şey öneren açılışlara istikrarlı biçimde yenildi. Özgünlük, somutluk ve cevaplanacak gerçek bir soru, kuru bir selamı her seferinde geçti." },
    { type: "h2", text: "Harvard Bulgusu: Soru Sormak Sizi Sevilir Kılıyor" },
    { type: "p", text: "Bu yalnızca bir uygulama verisi tuhaflığı değil. 2017'de Karen Huang, Michael Yeomans, Alison Wood Brooks, Julia Minson ve Francesca Gino, Journal of Personality and Social Psychology'de akılda kalıcı bir başlıkla bir çalışma serisi yayımladı: \"It Doesn't Hurt to Ask: Question-Asking Increases Liking\" (Sormanın Zararı Yok: Soru Sormak Beğenilmeyi Artırıyor). Yabancılar arasındaki canlı konuşmalarda, daha çok soru soranlar — özellikle karşı tarafın az önce söylediğinin üzerine inşa edilen **takip soruları** soranlar — konuşma partnerleri tarafından istikrarlı biçimde daha çok sevildi." },
    { type: "p", text: "En çarpıcı kısım sahadan geldi: araştırmacılar gerçek hızlı tanışma (speed dating) konuşmalarını analiz etti — 110 katılımcı, 2.000'den fazla buluşma. Daha çok takip sorusu soran katılımcılar, ikinci buluşma için \"evet\" alma olasılığı daha yüksek olanlardı. En çok soru soran üçte birlik dilim, en çok ikinci buluşma teklifini aldı. Soru sormak yalnızca kibarlık değildi; ölçülebilir biçimde çekiciydi." },
    { type: "h2", text: "Neden İşe Yarıyor: İyi Bir Soru Çift Yönlü Bir Hediyedir" },
    { type: "p", text: "Araştırmacıların tespit ettiği mekanizmanın adı **duyarlılık** (responsiveness): birine gerçek bir soru sorduğunuzda dinlediğinizi, anladığınızı ve önemsediğinizi sinyallersiniz. Cevap vermekse gerçekten iyi hissettirir — psikologlar, kendini ilgili bir dinleyiciye anlatmanın (self-disclosure) özünde keyifli olduğunu uzun süredir biliyor. Cevap veren kişi bu keyfi soruyu sorana, yani size atfeder. İyi bir soru karşınızdakine kendini ilginç hissettirir — ve bu süreçte sizi daha sevilir kılar." },
    { type: "p", text: "Bir malzeme daha var: sıra almak. Susan Sprecher ve ekibinin 2013'te Journal of Experimental Social Psychology'de yayımlanan çalışmasında, yabancılar ya sırayla soru sorup cevaplayarak ya da biri anlatırken diğeri yalnızca dinleyerek tanıştırıldı. Sıra alanlar anlamlı ölçüde daha fazla beğeni, yakınlık, benzerlik algısı ve keyif bildirdi. Bağ, bir kişinin performansından doğmuyor; **dönüşümlü** olmaktan doğuyor — sen sor, ben cevaplayayım; ben sorayım, sen cevapla." },
    { type: "h2", text: "Gerçekten Yanıt Alan Bir Sohbet Nasıl Başlatılır?" },
    { type: "p", text: "Veriyi ve psikolojiyi yan yana koyduğunuzda yol haritası kendiliğinden yazılıyor:" },
    { type: "ul", items: [
      "**Kuru selamı atlayın.** \"Selam\" karşı tarafa cevaplayacak hiçbir şey vermez — bütün emeği ona havale eder.",
      "**Somut bir şey hakkında sorun.** Karşınızdakinin gerçekten paylaştığı bir ayrıntıya değinin; somutluk, dikkat ettiğinizin kanıtıdır.",
      "**Açık uçlu yapın.** \"Evet\" ya da \"hayır\" ile cevaplanabilen bir soru genellikle öyle cevaplanır — ve sohbet orada ölür.",
      "**Cevabın üzerine soru sorun.** Araştırmadaki en güçlü sinyal ilk soru değil, ikincisiydi — dinlediğinizi gösteren soru.",
    ] },
    { type: "p", text: "Ama bir pürüz var: çoğu dating uygulamasında bunların tamamı şansa bırakılmış durumda. Uygulama sizi fotoğraflar üzerinden eşleştiriyor, boş bir sohbet kutusuna bırakıyor ve bir şekilde kendi kendinize usta bir soru soran olmanızı umuyor. Bilim, bağı soruların ve sıra almanın kurduğunu söylüyor — tasarımsa size boş bir ekran ve bir \"selam\" veriyor." },
    { type: "h2", accent: "green", text: "Qulo Soruyu İlk Temasın İçine Yerleştiriyor" },
    { type: "p", text: "Qulo'nun çekirdek mekaniği tam da araştırmanın işaret ettiği yerden başlıyor. Qulo'da biriyle eşleşmek için soğuk bir açılış mesajı atmazsınız — o kişinin **kendi yazdığı 2-10 soruyu** yanıtlarsınız. Daha ilk temasınız, nasıl düşündüğünüze ve neye değer verdiğinize dair gerçek soruların ve gerçek cevapların alışverişidir. O tuhaf \"şimdi ne yazsam?\" ânı ortadan kalkar; çünkü sohbet \"selam\"dan değil, doğrudan özden başlar." },
    { type: "p", text: "Açık olalım: hiçbir uygulama harika bir ilk alışverişin harika bir ilişkiye dönüşeceğini vaat edemez — araştırmanın dürüst hiçbir okuması bu iddiayı desteklemez. Araştırmanın desteklediği şey daha dar ve daha kullanışlı: sorular, kendini açma ve sıra alma, yabancıların birbirini sevmeye başlamasının güvenilir yolu. Qulo bu dinamiği şansa bırakmak yerine giriş kapısı yapıyor, hepsi bu." },
    { type: "quote", text: "En iyi ilk mesaj hiçbir zaman \"selam\" olmadı. Her zaman bir soruydu — gerçekten baktığınızı ve cevabı gerçekten önemsediğinizi gösteren bir soru." },
    { type: "h2", accent: "green", text: "Sonuç" },
    { type: "p", text: "Analiz edilen yarım milyon mesaj, jenerik selamların görmezden gelindiğini söylüyor. Harvard'ın konuşma çalışmaları, soru soranların — özellikle takip sorusu soranların — daha çok sevildiğini ve daha çok ikinci buluşma aldığını söylüyor. Deneysel psikoloji ise yakınlığın sırayla sorup cevaplayarak kurulduğunu söylüyor. Bağ böyle başlıyorsa, bunu neden boş bir sohbet kutusuna bırakasınız? Qulo her eşleşmeyi cevaplamaya değer sorularla başlatıyor. Qulo'yu indirin ve bir sonraki sohbetinizi bilimin işaret ettiği yerden başlatın." },
  ],
  de: [
    { type: "p", text: "Ihr habt gematcht. Du hast „hey“ getippt. Und dann… nichts. Wenn dir diese Schleife bekannt vorkommt, liegt das Problem wahrscheinlich nicht an dir — sondern an der Nachricht. Erste Nachrichten gehören zu den am gründlichsten vermessenen Momenten im Online-Dating, und die Daten aus Millionen von Gesprächen zeigen in eine Richtung: Begrüßungen werden ignoriert, Fragen bekommen Antworten. Die Psychologie hinter diesem Unterschied lohnt sich zu verstehen, denn sie verändert, wie du jedes Gespräch beginnst — in der App und außerhalb." },
    { type: "h2", text: "Die Daten: „Hey“ ist auf jeder App der schlechteste Opener" },
    { type: "p", text: "Das Datenteam von OkCupid analysierte über 500.000 erste Nachrichten auf der Plattform und stellte fest, dass die häufigsten Opener — „hi“, „hey“, „hello“ — Antwortquoten deutlich unter dem Durchschnitt hatten, während Nachrichten, die auf etwas Konkretes eingingen, spürbar besser abschnitten. Die denkbar generischste Nachricht erwies sich als die wirkungsloseste." },
    { type: "p", text: "Hinge machte das Experiment von der anderen Seite: 2015 testete das Unternehmen einen Monat lang rund 100 verschiedene Eröffnungssätze in seiner Nutzerbasis. Das Ergebnis war dieselbe Geschichte. Das klassische „hey, what's up?“ wurde durchgängig von Openern geschlagen, die eine persönliche Frage stellten oder etwas Konkretes vorschlugen. Originalität, Konkretheit und eine echte Frage, die man beantworten kann, schlugen die bloße Begrüßung jedes Mal." },
    { type: "h2", text: "Der Harvard-Befund: Wer Fragen stellt, wird gemocht" },
    { type: "p", text: "Das ist nicht bloß eine Kuriosität aus App-Daten. 2017 veröffentlichten Karen Huang, Michael Yeomans, Alison Wood Brooks, Julia Minson und Francesca Gino im Journal of Personality and Social Psychology eine Studienreihe mit einem einprägsamen Titel: „It Doesn't Hurt to Ask: Question-Asking Increases Liking“ (Fragen kostet nichts: Fragenstellen steigert die Sympathie). In echten Gesprächen zwischen Fremden wurden Menschen, die mehr Fragen stellten — vor allem **Anschlussfragen**, also die, die auf dem gerade Gesagten aufbauen —, von ihren Gesprächspartnern durchgängig mehr gemocht." },
    { type: "p", text: "Der eindrucksvollste Teil kam aus dem Feld: Die Forschenden analysierten echte Speed-Dating-Gespräche — 110 Teilnehmende, mehr als 2.000 Dates. Wer beim Speed-Dating mehr Anschlussfragen stellte, bekam mit höherer Wahrscheinlichkeit ein „Ja“ für ein zweites Date. Das obere Drittel der Fragensteller erhielt die meisten Angebote für ein zweites Date. Fragen zu stellen war nicht nur höflich; es war messbar attraktiv." },
    { type: "h2", text: "Warum es funktioniert: Eine gute Frage ist ein Geschenk in beide Richtungen" },
    { type: "p", text: "Der Mechanismus, den die Forschenden identifizierten, heißt **Responsivität**: Wenn du jemandem eine echte Frage stellst, signalisierst du, dass du zuhörst, dass du verstehst und dass dir die Person wichtig ist. Und Antworten fühlt sich wirklich gut an — Psychologen wissen seit Langem, dass Selbstoffenbarung, also einem interessierten Zuhörer von sich zu erzählen, an sich Freude macht. Die Person, die antwortet, schreibt diese Freude dir zu, dem Fragensteller. Eine gute Frage lässt das Gegenüber sich interessant fühlen — und macht dich dabei sympathischer." },
    { type: "p", text: "Es gibt noch eine Zutat: das Abwechseln. In einer Studie von 2013 im Journal of Experimental Social Psychology ließen Susan Sprecher und Kollegen Fremde sich entweder kennenlernen, indem sie sich beim Fragen und Antworten abwechselten, oder indem eine Person erzählte, während die andere nur zuhörte. Wer sich abwechselte, berichtete deutlich mehr Sympathie, Nähe, wahrgenommene Ähnlichkeit und Freude. Verbindung entsteht nicht, wenn eine Person eine Show abliefert; sie entsteht durch **Abwechseln** — du fragst, ich antworte, ich frage, du antwortest." },
    { type: "h2", text: "Wie man ein Gespräch beginnt, das wirklich eine Antwort bekommt" },
    { type: "p", text: "Legt man die Daten und die Psychologie nebeneinander, schreibt sich das Rezept von selbst:" },
    { type: "ul", items: ["**Lass die bloße Begrüßung weg.** Ein „Hey“ gibt dem Gegenüber nichts, worauf es antworten könnte — es wälzt die ganze Arbeit auf die andere Person ab.", "**Frag nach etwas Konkretem.** Beziehe dich auf ein Detail, das die Person tatsächlich geteilt hat; Konkretheit ist der Beweis, dass du aufmerksam warst.", "**Stell die Frage offen.** Eine Frage, die sich mit „ja“ oder „nein“ beantworten lässt, wird meist genau so beantwortet — und dort stirbt das Gespräch.", "**Hak bei der Antwort nach.** Das stärkste Signal in der Forschung war nicht die erste Frage, sondern die zweite — die, die zeigt, dass du zugehört hast."] },
    { type: "p", text: "Aber hier ist der Haken: In den meisten Dating-Apps bleibt all das dem Zufall überlassen. Die App matcht euch über Fotos, setzt euch in ein leeres Chatfenster und hofft, dass du irgendwie von allein zum geübten Fragensteller wirst. Die Wissenschaft sagt, Fragen und Abwechseln schaffen Verbindung — und das Design gibt dir einen leeren Bildschirm und ein „hey“." },
    { type: "h2", accent: "green", text: "Qulo baut die Frage in den ersten Kontakt ein" },
    { type: "p", text: "Qulos Kernmechanik beginnt genau dort, wo die Forschung hinzeigt. Um auf Qulo mit jemandem zu matchen, schickst du keinen kalten Opener — du beantwortest **2-10 Fragen, die diese Person selbst geschrieben hat**. Dein allererster Kontakt ist bereits ein Austausch echter Fragen und echter Antworten darüber, wie du denkst und was dir wichtig ist. Der unangenehme „Was soll ich bloß schreiben?“-Moment entfällt, denn das Gespräch beginnt mitten im Inhalt — nicht bei „hey“." },
    { type: "p", text: "Um es klar zu sagen: Keine App kann versprechen, dass aus einem großartigen ersten Austausch eine großartige Beziehung wird — keine ehrliche Lesart der Forschung stützt diese Behauptung. Was die Forschung stützt, ist enger und nützlicher: Fragen, Selbstoffenbarung und Abwechseln sind der verlässliche Weg, auf dem Fremde beginnen, sich zu mögen. Qulo macht diese Dynamik einfach zum Einstieg, statt sie dem Glück zu überlassen." },
    { type: "quote", text: "Die beste erste Nachricht war nie „hey“. Es war immer eine Frage — eine, die zeigt, dass du wirklich hingeschaut hast und dich die Antwort wirklich interessiert." },
    { type: "h2", accent: "green", text: "Fazit" },
    { type: "p", text: "Eine halbe Million analysierter Nachrichten sagt: Generische Begrüßungen werden ignoriert. Harvards Gesprächsstudien sagen: Wer Fragen stellt — vor allem Anschlussfragen —, wird mehr gemocht und bekommt mehr zweite Dates. Und die experimentelle Psychologie sagt: Nähe entsteht, wenn man sich beim Fragen und Antworten abwechselt. Wenn Verbindung so beginnt, warum sie einem leeren Chatfenster überlassen? Qulo startet jedes Match mit Fragen, die eine Antwort wert sind. Lade Qulo herunter und beginne dein nächstes Gespräch dort, wo es laut Wissenschaft beginnen sollte." },
  ],
  fr: [
    { type: "p", text: "Vous avez matché. Vous avez écrit « hey ». Et puis… rien. Si cette boucle vous semble familière, le problème ne vient probablement pas de vous — mais du message. Le premier message est l'un des moments les plus mesurés du dating en ligne, et les données issues de millions de conversations pointent toutes dans la même direction : les salutations sont ignorées, les questions obtiennent des réponses. La psychologie derrière cet écart mérite qu'on s'y attarde, car elle change la façon dont vous entamez chaque conversation — sur une appli comme en dehors." },
    { type: "h2", text: "Les données : « hey » est la pire entrée en matière sur toutes les applis" },
    { type: "p", text: "L'équipe data d'OkCupid a analysé plus de 500 000 premiers messages sur la plateforme et a constaté que les ouvertures les plus courantes — « hi », « hey », « hello » — affichaient des taux de réponse nettement inférieurs à la moyenne, tandis que les messages qui rebondissaient sur quelque chose de précis s'en sortaient bien mieux. Le message le plus générique possible s'est révélé être le moins efficace." },
    { type: "p", text: "Hinge a mené l'expérience depuis l'autre côté : en 2015, l'entreprise a testé une centaine de phrases d'accroche différentes auprès de ses utilisateurs pendant un mois. Le résultat racontait la même histoire. Le classique « hey, what's up? » (« salut, ça va ? ») était systématiquement battu par les ouvertures qui posaient une question personnalisée ou proposaient quelque chose de concret. L'originalité, la précision et une vraie question à laquelle répondre l'emportaient à chaque fois sur une simple salutation." },
    { type: "h2", text: "La découverte de Harvard : poser des questions vous rend plus sympathique" },
    { type: "p", text: "Ce n'est pas qu'une curiosité statistique propre aux applis. En 2017, Karen Huang, Michael Yeomans, Alison Wood Brooks, Julia Minson et Francesca Gino ont publié une série d'études dans le Journal of Personality and Social Psychology sous un titre mémorable : « It Doesn't Hurt to Ask: Question-Asking Increases Liking » (Demander ne coûte rien : poser des questions augmente la sympathie). Dans des conversations réelles entre inconnus, les personnes qui posaient le plus de questions — en particulier des **questions de relance**, celles qui s'appuient sur ce que l'autre vient de dire — étaient systématiquement mieux appréciées par leurs interlocuteurs." },
    { type: "p", text: "Le résultat le plus frappant venait du terrain : les chercheurs ont analysé de vraies conversations de speed dating — 110 participants, plus de 2 000 rendez-vous. Les personnes qui posaient le plus de questions de relance avaient plus de chances d'obtenir un « oui » pour un second rendez-vous. Le tiers supérieur des poseurs de questions a reçu le plus de propositions de second rendez-vous. Poser des questions n'était pas seulement poli ; c'était mesurablement séduisant." },
    { type: "h2", text: "Pourquoi ça marche : une bonne question est un cadeau à double sens" },
    { type: "p", text: "Le mécanisme identifié par les chercheurs s'appelle la **réactivité** (responsiveness) : quand vous posez une vraie question à quelqu'un, vous signalez que vous écoutez, que vous comprenez et que vous vous souciez de lui. Et répondre fait sincèrement du bien — les psychologues savent depuis longtemps que la révélation de soi, parler de soi à un auditeur intéressé, est intrinsèquement agréable. La personne qui répond attribue ce plaisir à celle qui a posé la question, c'est-à-dire à vous. Une bonne question donne à l'autre le sentiment d'être intéressant — et vous rend plus sympathique au passage." },
    { type: "p", text: "Il y a un ingrédient de plus : l'alternance. Dans une étude publiée en 2013 dans le Journal of Experimental Social Psychology, Susan Sprecher et ses collègues ont fait faire connaissance à des inconnus soit en alternant questions et réponses à tour de rôle, soit en laissant une personne se confier pendant que l'autre se contentait d'écouter. Ceux qui alternaient rapportaient significativement plus de sympathie, de proximité, de similarité perçue et de plaisir. Le lien ne naît pas de la performance d'une seule personne ; il naît de l'**alternance** — vous demandez, je réponds, je demande, vous répondez." },
    { type: "h2", text: "Comment entamer une conversation qui obtient vraiment une réponse" },
    { type: "p", text: "Mettez les données et la psychologie côte à côte, et la marche à suivre s'écrit toute seule :" },
    { type: "ul", items: ["**Sautez la salutation sèche.** « Hey » ne donne rien à quoi répondre — il délègue tout l'effort à l'autre.", "**Interrogez sur quelque chose de précis.** Faites référence à un détail que la personne a réellement partagé ; la précision est la preuve que vous avez été attentif.", "**Posez une question ouverte.** Une question à laquelle on peut répondre par « oui » ou « non » recevra généralement cette réponse — et la conversation s'arrête là.", "**Rebondissez sur la réponse.** Le signal le plus fort de la recherche n'était pas la première question, mais la seconde — celle qui montre que vous avez écouté."] },
    { type: "p", text: "Voici pourtant le hic : sur la plupart des applis de rencontre, tout cela est laissé au hasard. L'appli vous matche sur des photos, vous dépose dans une boîte de discussion vide et espère que vous deviendrez, tout seul, un poseur de questions aguerri. La science dit que les questions et l'alternance construisent le lien — et le design vous donne un écran vide et un « hey »." },
    { type: "h2", accent: "green", text: "Qulo intègre la question dès le premier contact" },
    { type: "p", text: "La mécanique centrale de Qulo commence exactement là où la recherche pointe. Pour matcher avec quelqu'un sur Qulo, vous n'envoyez pas une accroche à froid — vous répondez aux **2-10 questions que cette personne a écrites elle-même**. Votre tout premier contact est déjà un échange de vraies questions et de vraies réponses sur votre façon de penser et ce qui compte pour vous. Le moment gênant du « qu'est-ce que je peux bien dire ? » disparaît, parce que la conversation commence en plein cœur du sujet, pas à « hey »." },
    { type: "p", text: "Soyons clairs : aucune appli ne peut promettre qu'un excellent premier échange deviendra une excellente relation — aucune lecture honnête de la recherche ne soutient cette affirmation. Ce que la recherche soutient est plus modeste et plus utile : les questions, la révélation de soi et l'alternance sont la manière fiable dont des inconnus commencent à s'apprécier. Qulo fait simplement de cette dynamique la porte d'entrée, au lieu de la laisser au hasard." },
    { type: "quote", text: "Le meilleur premier message n'a jamais été « hey ». Ça a toujours été une question — une question qui montre que vous avez vraiment regardé, et que la réponse vous importe vraiment." },
    { type: "h2", accent: "green", text: "Conclusion" },
    { type: "p", text: "Un demi-million de messages analysés disent que les salutations génériques sont ignorées. Les études de Harvard sur la conversation disent que ceux qui posent des questions — surtout des questions de relance — sont mieux appréciés et obtiennent plus de seconds rendez-vous. Et la psychologie expérimentale dit que c'est en alternant questions et réponses que la proximité se construit réellement. Si c'est ainsi que naît le lien, pourquoi le confier à une boîte de discussion vide ? Qulo fait démarrer chaque match par des questions qui valent la peine d'y répondre. Téléchargez Qulo et commencez votre prochaine conversation là où la science dit qu'elle devrait commencer." },
  ],
  es: [
    { type: "p", text: "Hicieron match. Escribiste \"hey\". Y después… nada. Si este bucle te suena, el problema probablemente no eres tú — es el mensaje. El primer mensaje es uno de los momentos más medidos del dating online, y los datos de millones de conversaciones apuntan en una sola dirección: los saludos se ignoran, las preguntas reciben respuesta. Vale la pena entender la psicología detrás de esa brecha, porque cambia cómo empiezas cada conversación — dentro y fuera de la app." },
    { type: "h2", text: "Los datos: \"hey\" es la peor apertura en todas las apps" },
    { type: "p", text: "El equipo de datos de OkCupid analizó más de 500.000 primeros mensajes en la plataforma y descubrió que las aperturas más comunes — \"hi\", \"hey\", \"hello\" — tenían tasas de respuesta muy por debajo de la media, mientras que los mensajes que se enganchaban a algo concreto funcionaban notablemente mejor. El mensaje más genérico posible resultó ser el menos eficaz." },
    { type: "p", text: "Hinge hizo el experimento desde el otro lado: en 2015 la empresa probó unas 100 frases de apertura distintas entre sus usuarios durante un mes. El resultado fue la misma historia. El clásico \"hey, what's up?\" (\"ey, ¿qué tal?\") fue superado sistemáticamente por aperturas que hacían una pregunta personalizada o proponían algo concreto. La originalidad, la especificidad y una pregunta real que responder ganaban siempre a un saludo pelado." },
    { type: "h2", text: "El hallazgo de Harvard: hacer preguntas hace que le gustes a la gente" },
    { type: "p", text: "Esto no es solo una rareza de los datos de las apps. En 2017, Karen Huang, Michael Yeomans, Alison Wood Brooks, Julia Minson y Francesca Gino publicaron una serie de estudios en el Journal of Personality and Social Psychology con un título memorable: \"It Doesn't Hurt to Ask: Question-Asking Increases Liking\" (Preguntar no hace daño: hacer preguntas aumenta la simpatía). En conversaciones en vivo entre desconocidos, quienes hacían más preguntas — sobre todo **preguntas de seguimiento**, las que construyen sobre lo que la otra persona acaba de decir — caían sistemáticamente mejor a sus interlocutores." },
    { type: "p", text: "La parte más llamativa vino del terreno: los investigadores analizaron conversaciones reales de speed dating — 110 participantes, más de 2.000 citas. Quienes hacían más preguntas de seguimiento tenían más probabilidades de recibir un \"sí\" a una segunda cita. El tercio que más preguntaba recibió la mayor cantidad de propuestas de segunda cita. Preguntar no era solo de buena educación; era medible y atractivo." },
    { type: "h2", text: "Por qué funciona: una buena pregunta es un regalo en dos direcciones" },
    { type: "p", text: "El mecanismo que identificaron los investigadores se llama **receptividad** (responsiveness): cuando le haces a alguien una pregunta de verdad, le señalas que escuchas, que entiendes y que te importa. Y responder sienta genuinamente bien — los psicólogos saben desde hace mucho que la autorrevelación, hablar de uno mismo ante un oyente interesado, es intrínsecamente placentera. Quien responde atribuye ese placer a ti, la persona que pregunta. Una buena pregunta hace que la otra persona se sienta interesante — y de paso te hace más agradable a ti." },
    { type: "p", text: "Hay un ingrediente más: los turnos. En un estudio de 2013 en el Journal of Experimental Social Psychology, Susan Sprecher y sus colegas hicieron que desconocidos se conocieran, o bien turnándose para preguntar y responder, o bien con una persona hablando de sí misma mientras la otra solo escuchaba. Quienes se turnaron reportaron significativamente más simpatía, cercanía, sensación de similitud y disfrute. La conexión no nace de que una persona actúe para la otra; nace de **alternar** — tú preguntas, yo respondo; yo pregunto, tú respondes." },
    { type: "h2", text: "Cómo empezar una conversación que de verdad recibe respuesta" },
    { type: "p", text: "Junta los datos con la psicología y el manual se escribe solo:" },
    { type: "ul", items: ["**Sáltate el saludo pelado.** Un \"hey\" no le da a la otra persona nada que responder — le delega todo el esfuerzo.", "**Pregunta por algo concreto.** Menciona un detalle que esa persona realmente compartió; la especificidad es la prueba de que prestaste atención.", "**Hazla abierta.** Una pregunta que se puede responder con \"sí\" o \"no\" normalmente se responderá así — y la conversación muere ahí.", "**Haz seguimiento a la respuesta.** La señal más fuerte de la investigación no era la primera pregunta sino la segunda — la que demuestra que escuchaste."] },
    { type: "p", text: "Pero aquí está la trampa: en la mayoría de las apps de dating, todo esto queda al azar. La app te empareja por fotos, te suelta en un chat vacío y espera que, de algún modo, te conviertas por tu cuenta en un experto en hacer preguntas. La ciencia dice que las preguntas y los turnos construyen la conexión — y el diseño te da una pantalla en blanco y un \"hey\"." },
    { type: "h2", accent: "green", text: "Qulo integra la pregunta en el primer contacto" },
    { type: "p", text: "La mecánica central de Qulo empieza exactamente donde apunta la investigación. Para hacer match con alguien en Qulo no envías una apertura en frío — respondes **de 2 a 10 preguntas que esa persona escribió por sí misma**. Tu primerísimo contacto ya es un intercambio de preguntas reales y respuestas reales sobre cómo piensas y qué te importa. El incómodo momento de \"¿y ahora qué le digo?\" desaparece, porque la conversación empieza en plena sustancia, no en un \"hey\"." },
    { type: "p", text: "Seamos claros: ninguna app puede prometer que un gran primer intercambio se convierta en una gran relación — ninguna lectura honesta de la investigación respalda esa afirmación. Lo que la investigación sí respalda es algo más acotado y más útil: las preguntas, la autorrevelación y los turnos son la forma fiable en que dos desconocidos empiezan a gustarse. Qulo simplemente convierte esa dinámica en el punto de entrada en lugar de dejarla a la suerte." },
    { type: "quote", text: "El mejor primer mensaje nunca fue un \"hey\". Siempre fue una pregunta — una que demuestra que de verdad miraste y que de verdad te importa la respuesta." },
    { type: "h2", accent: "green", text: "Conclusión" },
    { type: "p", text: "Medio millón de mensajes analizados dicen que los saludos genéricos se ignoran. Los estudios sobre conversación de Harvard dicen que quienes preguntan — sobre todo quienes hacen preguntas de seguimiento — caen mejor y consiguen más segundas citas. Y la psicología experimental dice que turnarse para preguntar y responder es como se forma realmente la cercanía. Si así es como empieza la conexión, ¿por qué dejarla en manos de un chat en blanco? Qulo arranca cada match con preguntas que merecen respuesta. Descarga Qulo y empieza tu próxima conversación donde la ciencia dice que debería empezar." },
  ],
  ar: [
    { type: "p", text: "حدث التطابق. كتبتَ \"hey\" (مرحبًا). ثم… لا شيء. إذا كانت هذه الحلقة مألوفة لك، فالمشكلة على الأرجح ليست فيك — بل في الرسالة. الرسائل الأولى من أكثر اللحظات التي تُقاس بدقة في عالم المواعدة عبر الإنترنت، والبيانات المستخلصة من ملايين المحادثات تشير في اتجاه واحد: التحيات تُتجاهَل، والأسئلة تحصل على إجابات. السيكولوجيا الكامنة وراء هذه الفجوة تستحق الفهم، لأنها تغيّر طريقة بدئك لكل محادثة — داخل التطبيق وخارجه." },
    { type: "h2", text: "البيانات: \"مرحبًا\" هي أسوأ افتتاحية في كل التطبيقات" },
    { type: "p", text: "حلّل فريق البيانات في OkCupid أكثر من 500,000 رسالة أولى على المنصة، ووجد أن الافتتاحيات الأكثر شيوعًا — \"hi\" و\"hey\" و\"hello\" — كانت معدلات الرد عليها أدنى بكثير من المتوسط، بينما حققت الرسائل التي تفاعلت مع شيء محدد نتائج أفضل بوضوح. تبيّن أن أكثر الرسائل عمومية على الإطلاق هي الأقل فعالية." },
    { type: "p", text: "أما Hinge فأجرت التجربة من الجانب الآخر: في عام 2015 اختبرت الشركة نحو 100 جملة افتتاحية مختلفة على قاعدة مستخدميها لمدة شهر. وكانت النتيجة القصة نفسها. عبارة \"hey, what's up?\" الكلاسيكية تفوقت عليها باستمرار الافتتاحيات التي طرحت سؤالًا شخصيًا أو اقترحت شيئًا ملموسًا. الجِدّة والتحديد ووجود سؤال حقيقي يُجاب عنه تغلبت على التحية المجردة في كل مرة." },
    { type: "h2", text: "اكتشاف هارفارد: طرح الأسئلة يجعل الناس يحبونك" },
    { type: "p", text: "هذه ليست مجرد مفارقة في بيانات التطبيقات. ففي عام 2017 نشر كل من Karen Huang وMichael Yeomans وAlison Wood Brooks وJulia Minson وFrancesca Gino سلسلة من الدراسات في مجلة Journal of Personality and Social Psychology تحت عنوان لا يُنسى: \"It Doesn't Hurt to Ask: Question-Asking Increases Liking\" (لا ضير في السؤال: طرح الأسئلة يزيد الإعجاب). عبر محادثات حية بين غرباء، كان الأشخاص الذين طرحوا أسئلة أكثر — وخاصة **أسئلة المتابعة**، تلك التي تبني على ما قاله الطرف الآخر للتو — يحظون باستمرار بإعجاب أكبر لدى شركائهم في المحادثة." },
    { type: "p", text: "أما الجزء الأكثر إثارة فجاء من الميدان: حلّل الباحثون محادثات حقيقية من لقاءات التعارف السريع (speed dating) — 110 مشاركين وأكثر من 2,000 لقاء. المشاركون الذين طرحوا أسئلة متابعة أكثر كانوا أوفر حظًا في الحصول على \"نعم\" لموعد ثانٍ. وحصل الثلث الأعلى من طارحي الأسئلة على أكبر عدد من عروض المواعيد الثانية. لم يكن السؤال مجرد لباقة؛ بل كان جذابًا بشكل قابل للقياس." },
    { type: "h2", text: "لماذا ينجح الأمر: السؤال الجيد هدية في الاتجاهين" },
    { type: "p", text: "الآلية التي حددها الباحثون تُسمى **التجاوب** (responsiveness): عندما تطرح على شخص سؤالًا حقيقيًا، فأنت تُشير إلى أنك تُصغي، وأنك تفهم، وأنك تهتم. والإجابة بدورها تمنح شعورًا طيبًا حقًا — فعلماء النفس يعرفون منذ زمن أن الإفصاح عن الذات، أي الحديث عن نفسك أمام مستمع مهتم، ممتع في جوهره. والشخص المُجيب يَنسب هذه المتعة إليك أنت، صاحب السؤال. السؤال الجيد يجعل الطرف الآخر يشعر بأنه مثير للاهتمام — ويجعلك في الوقت نفسه أكثر قابلية للمحبة." },
    { type: "p", text: "وهناك مكوّن إضافي: تبادل الأدوار. ففي دراسة نُشرت عام 2013 في مجلة Journal of Experimental Social Psychology، جعلت Susan Sprecher وزملاؤها غرباء يتعارفون إما بالتناوب على طرح الأسئلة والإجابة عنها، أو بأن يُفصح أحدهما عن نفسه بينما يكتفي الآخر بالاستماع. أفاد المتناوبون بقدر أكبر بكثير من الإعجاب والقرب والشعور بالتشابه والاستمتاع. الرابطة لا تنشأ من أداء شخص واحد؛ بل تنشأ من **التبادل** — تسأل أنت فأجيب أنا، ثم أسأل أنا فتجيب أنت." },
    { type: "h2", text: "كيف تبدأ محادثة تحصل فعلًا على رد" },
    { type: "p", text: "اجمع البيانات والسيكولوجيا معًا، وستكتب خطة العمل نفسها بنفسها:" },
    { type: "ul", items: ["**تجاوز التحية المجردة.** \"مرحبًا\" لا تمنح الطرف الآخر شيئًا يجيب عنه — إنها تُلقي بكل الجهد على عاتقه.", "**اسأل عن شيء محدد.** أشِر إلى تفصيلة شاركها الطرف الآخر فعلًا؛ فالتحديد دليل على أنك انتبهت.", "**اجعل سؤالك مفتوحًا.** السؤال الذي يمكن الإجابة عنه بـ\"نعم\" أو \"لا\" غالبًا ما يُجاب عنه كذلك — وهناك تموت المحادثة.", "**تابِع الإجابة بسؤال.** أقوى إشارة في البحث لم تكن السؤال الأول بل الثاني — السؤال الذي يُظهر أنك أصغيت."] },
    { type: "p", text: "لكن هنا تكمن المعضلة: في معظم تطبيقات المواعدة، يُترك كل هذا للصدفة. يطابقك التطبيق بناءً على الصور، ويلقي بك في صندوق دردشة فارغ، ويأمل أن تتحول بطريقة ما إلى بارع في طرح الأسئلة من تلقاء نفسك. يقول العلم إن الأسئلة وتبادل الأدوار هما ما يبني الرابطة — بينما يمنحك التصميم شاشة فارغة و\"مرحبًا\"." },
    { type: "h2", accent: "green", text: "Qulo يُدمج السؤال في أول تواصل" },
    { type: "p", text: "الآلية الأساسية في Qulo تبدأ تحديدًا من حيث يشير البحث. للتطابق مع شخص ما على Qulo، لا تُرسل افتتاحية باردة — بل تجيب عن **2-10 أسئلة كتبها ذلك الشخص بنفسه**. أول تواصل بينكما هو أصلًا تبادل لأسئلة حقيقية وإجابات حقيقية عن طريقة تفكيرك وما يهمّك. تختفي لحظة الحرج \"ماذا أكتب أصلًا؟\"، لأن المحادثة تبدأ من صميم المضمون، لا من \"مرحبًا\"." },
    { type: "p", text: "ولنكن واضحين: لا يمكن لأي تطبيق أن يَعِد بأن تبادلًا أوليًا رائعًا سيتحول إلى علاقة رائعة — فلا قراءة أمينة للبحث تدعم هذا الادعاء. ما يدعمه البحث أضيق نطاقًا وأكثر فائدة: الأسئلة والإفصاح عن الذات وتبادل الأدوار هي الطريقة الموثوقة التي يبدأ بها الغرباء بمحبة بعضهم بعضًا. كل ما يفعله Qulo هو جعل هذه الديناميكية نقطة الانطلاق بدلًا من تركها للحظ." },
    { type: "quote", text: "أفضل رسالة أولى لم تكن يومًا \"مرحبًا\". كانت دائمًا سؤالًا — سؤالًا يُظهر أنك نظرت فعلًا، وأنك تهتم فعلًا بالإجابة." },
    { type: "h2", accent: "green", text: "الخلاصة" },
    { type: "p", text: "نصف مليون رسالة خضعت للتحليل تقول إن التحيات العامة تُتجاهَل. ودراسات المحادثة في هارفارد تقول إن طارحي الأسئلة — وخاصة طارحي أسئلة المتابعة — يحظون بإعجاب أكبر ويحصلون على مواعيد ثانية أكثر. وعلم النفس التجريبي يقول إن التناوب على السؤال والإجابة هو الطريقة التي يتشكل بها القرب فعليًا. إذا كانت الرابطة تبدأ هكذا، فلماذا تتركها لصندوق دردشة فارغ؟ Qulo يبدأ كل تطابق بأسئلة تستحق الإجابة. حمِّل Qulo وابدأ محادثتك القادمة من حيث يقول العلم إنها يجب أن تبدأ." },
  ],
  ru: [
    { type: "p", text: "Вы совпали. Вы написали «привет». А потом… тишина. Если этот сценарий вам знаком, проблема, скорее всего, не в вас — а в сообщении. Первое сообщение — один из самых тщательно измеряемых моментов онлайн-знакомств, и данные миллионов разговоров указывают в одну сторону: приветствия игнорируют, на вопросы отвечают. Психологию этого разрыва стоит понять, потому что она меняет то, как вы начинаете любой разговор — в приложении и за его пределами." },
    { type: "h2", text: "Данные: «hey» — худшее начало в любом приложении" },
    { type: "p", text: "Команда аналитиков OkCupid проанализировала более 500 000 первых сообщений на платформе и обнаружила, что у самых распространённых открывающих фраз — «hi», «hey», «hello» — доля ответов была заметно ниже средней, тогда как сообщения, цепляющиеся за что-то конкретное, работали существенно лучше. Самое шаблонное из возможных сообщений оказалось самым неэффективным." },
    { type: "p", text: "Hinge провёл эксперимент с другой стороны: в 2015 году компания в течение месяца тестировала на своих пользователях около 100 разных первых фраз. Итог оказался тем же. Классическое «hey, what's up?» («привет, как дела?») стабильно проигрывало фразам, которые задавали персонализированный вопрос или предлагали что-то конкретное. Оригинальность, конкретика и настоящий вопрос, на который есть что ответить, каждый раз побеждали голое приветствие." },
    { type: "h2", text: "Гарвардский вывод: тот, кто задаёт вопросы, больше нравится" },
    { type: "p", text: "Это не просто причуда статистики приложений. В 2017 году Karen Huang, Michael Yeomans, Alison Wood Brooks, Julia Minson и Francesca Gino опубликовали в Journal of Personality and Social Psychology серию исследований с запоминающимся названием: \"It Doesn't Hurt to Ask: Question-Asking Increases Liking\" («Спросить не вредно: вопросы повышают симпатию»). В живых разговорах между незнакомцами те, кто задавал больше вопросов — особенно **уточняющих вопросов**, которые опираются на только что сказанное собеседником, — стабильно больше нравились своим партнёрам по разговору." },
    { type: "p", text: "Самое яркое пришло из полевых данных: исследователи проанализировали реальные разговоры на спид-дейтинге — 110 участников, более 2 000 свиданий. Те, кто задавал больше уточняющих вопросов, чаще получали «да» на второе свидание. Верхняя треть по числу вопросов получила больше всего приглашений на вторую встречу. Спрашивать было не просто вежливо — это было измеримо привлекательно." },
    { type: "h2", text: "Почему это работает: хороший вопрос — подарок обоим" },
    { type: "p", text: "Механизм, который выявили исследователи, называется **отзывчивость** (responsiveness): задавая человеку настоящий вопрос, вы сигнализируете, что слушаете, понимаете и вам не всё равно. А отвечать по-настоящему приятно — психологи давно знают, что самораскрытие, рассказ о себе заинтересованному слушателю, приятно само по себе. Это удовольствие отвечающий приписывает вам — тому, кто спросил. Хороший вопрос даёт собеседнику почувствовать себя интересным — и заодно делает вас более симпатичным." },
    { type: "p", text: "Есть ещё один ингредиент: чередование. В исследовании 2013 года в Journal of Experimental Social Psychology Susan Sprecher с коллегами знакомила незнакомцев двумя способами: либо они по очереди задавали вопросы и отвечали, либо один рассказывал, а другой только слушал. Те, кто чередовался, сообщали о значимо большей симпатии, близости, ощущении сходства и удовольствии. Связь рождается не из выступления одного человека, а из **обмена по очереди** — вы спрашиваете, я отвечаю, я спрашиваю, вы отвечаете." },
    { type: "h2", text: "Как начать разговор, на который действительно ответят" },
    { type: "p", text: "Сложите данные и психологию вместе — и план напишется сам:" },
    { type: "ul", items: ["**Пропустите голое приветствие.** «Привет» не даёт собеседнику ничего, на что можно ответить, — вся работа перекладывается на него.", "**Спросите о чём-то конкретном.** Зацепитесь за деталь, которой человек действительно поделился; конкретика — доказательство того, что вы были внимательны.", "**Сделайте вопрос открытым.** На вопрос, на который можно ответить «да» или «нет», обычно так и отвечают — и разговор на этом умирает.", "**Задайте вопрос к ответу.** Самым сильным сигналом в исследованиях был не первый вопрос, а второй — тот, что показывает: вы слушали."] },
    { type: "p", text: "Но есть загвоздка: в большинстве дейтинг-приложений всё это отдано на волю случая. Приложение сводит вас по фотографиям, бросает в пустое окно чата и надеется, что вы как-нибудь сами станете мастером вопросов. Наука говорит, что связь строят вопросы и чередование, — а дизайн выдаёт вам пустой экран и «привет»." },
    { type: "h2", accent: "green", text: "Qulo встраивает вопрос в самый первый контакт" },
    { type: "p", text: "Ключевая механика Qulo начинается ровно там, куда указывают исследования. Чтобы совпасть с кем-то в Qulo, вы не отправляете холодное первое сообщение — вы отвечаете на **2-10 вопросов, которые этот человек написал сам**. Ваш самый первый контакт — это уже обмен настоящими вопросами и настоящими ответами о том, как вы думаете и что для вас важно. Неловкий момент «что вообще написать?» исчезает, потому что разговор начинается сразу с сути, а не с «привет»." },
    { type: "p", text: "Скажем прямо: ни одно приложение не может обещать, что отличный первый обмен превратится в отличные отношения — ни одно честное прочтение исследований такого утверждения не поддерживает. Что исследования действительно подтверждают, так это нечто более узкое и более полезное: вопросы, самораскрытие и чередование — надёжный путь, которым незнакомцы начинают нравиться друг другу. Qulo просто делает эту динамику точкой входа, вместо того чтобы оставлять её на волю удачи." },
    { type: "quote", text: "Лучшее первое сообщение никогда не было «привет». Это всегда был вопрос — такой, который показывает, что вы действительно смотрели и вам действительно важен ответ." },
    { type: "h2", accent: "green", text: "Вывод" },
    { type: "p", text: "Полмиллиона проанализированных сообщений говорят: шаблонные приветствия игнорируют. Гарвардские исследования разговоров говорят: те, кто задаёт вопросы — особенно уточняющие, — больше нравятся и чаще получают второе свидание. А экспериментальная психология говорит: близость возникает, когда вы по очереди спрашиваете и отвечаете. Если связь начинается именно так, зачем доверять её пустому окну чата? Qulo начинает каждый мэтч с вопросов, на которые хочется ответить. Скачайте Qulo и начните следующий разговор там, где, по мнению науки, он и должен начинаться." },
  ],
  pt: [
    { type: "p", text: "Vocês deram match. Você digitou \"oi\". E depois… nada. Se esse ciclo soa familiar, o problema provavelmente não é você — é a mensagem. As primeiras mensagens estão entre os momentos mais medidos do namoro online, e os dados de milhões de conversas apontam em uma única direção: cumprimentos são ignorados, perguntas recebem respostas. Vale a pena entender a psicologia por trás dessa diferença, porque ela muda a forma como você começa qualquer conversa — dentro ou fora do aplicativo." },
    { type: "h2", text: "Os dados: \"oi\" é a pior abertura em qualquer aplicativo" },
    { type: "p", text: "A equipe de dados do OkCupid analisou mais de 500.000 primeiras mensagens na plataforma e descobriu que as aberturas mais comuns — \"hi\", \"hey\", \"hello\" — tinham taxas de resposta bem abaixo da média, enquanto mensagens que se conectavam a algo específico se saíam visivelmente melhor. A mensagem mais genérica possível acabou sendo a menos eficaz." },
    { type: "p", text: "O Hinge fez o experimento pelo outro lado: em 2015, a empresa testou cerca de 100 frases de abertura diferentes com sua base de usuários durante um mês. O resultado contou a mesma história. O clássico \"hey, what's up?\" (\"e aí, tudo bem?\") foi consistentemente superado por aberturas que faziam uma pergunta personalizada ou propunham algo concreto. Originalidade, especificidade e uma pergunta de verdade para responder venceram um cumprimento seco todas as vezes." },
    { type: "h2", text: "A descoberta de Harvard: fazer perguntas faz as pessoas gostarem de você" },
    { type: "p", text: "Isso não é só uma curiosidade dos dados de aplicativos. Em 2017, Karen Huang, Michael Yeomans, Alison Wood Brooks, Julia Minson e Francesca Gino publicaram uma série de estudos no Journal of Personality and Social Psychology com um título memorável: \"It Doesn't Hurt to Ask: Question-Asking Increases Liking\" (Perguntar não faz mal: fazer perguntas aumenta a simpatia). Em conversas ao vivo entre desconhecidos, as pessoas que faziam mais perguntas — especialmente **perguntas de acompanhamento**, aquelas que se apoiam no que a outra pessoa acabou de dizer — eram consistentemente mais queridas por seus interlocutores." },
    { type: "p", text: "A parte mais impressionante veio do campo: os pesquisadores analisaram conversas reais de speed dating — 110 participantes, mais de 2.000 encontros. Os participantes que faziam mais perguntas de acompanhamento tinham mais chances de receber um \"sim\" para um segundo encontro. O terço que mais fazia perguntas recebeu o maior número de convites para um segundo encontro. Perguntar não era só educado; era mensuravelmente atraente." },
    { type: "h2", text: "Por que funciona: uma boa pergunta é um presente de mão dupla" },
    { type: "p", text: "O mecanismo que os pesquisadores identificaram se chama **responsividade**: quando você faz uma pergunta de verdade a alguém, sinaliza que está ouvindo, que entende e que se importa. E responder é genuinamente gostoso — os psicólogos sabem há muito tempo que a autorrevelação, falar de si mesmo para um ouvinte interessado, é intrinsecamente prazerosa. Quem responde atribui esse prazer a você, quem perguntou. Uma boa pergunta faz a outra pessoa se sentir interessante — e, de quebra, torna você mais querido." },
    { type: "p", text: "Há mais um ingrediente: a alternância. Em um estudo de 2013 no Journal of Experimental Social Psychology, Susan Sprecher e colegas fizeram desconhecidos se conhecerem ou revezando-se em perguntar e responder, ou com uma pessoa se abrindo enquanto a outra apenas ouvia. Quem se revezava relatou significativamente mais simpatia, proximidade, percepção de semelhança e prazer na conversa. A conexão não nasce de uma pessoa fazendo um show; nasce da **alternância** — você pergunta, eu respondo, eu pergunto, você responde." },
    { type: "h2", text: "Como começar uma conversa que realmente recebe resposta" },
    { type: "p", text: "Junte os dados e a psicologia, e o manual se escreve sozinho:" },
    { type: "ul", items: ["**Pule o cumprimento seco.** \"Oi\" não dá à outra pessoa nada para responder — terceiriza todo o esforço para ela.", "**Pergunte sobre algo específico.** Mencione um detalhe que a pessoa realmente compartilhou; a especificidade é a prova de que você prestou atenção.", "**Faça uma pergunta aberta.** Uma pergunta que pode ser respondida com \"sim\" ou \"não\" geralmente será — e a conversa morre ali.", "**Aprofunde a resposta.** O sinal mais forte na pesquisa não foi a primeira pergunta, mas a segunda — aquela que mostra que você ouviu."] },
    { type: "p", text: "Mas aqui está o porém: na maioria dos aplicativos de namoro, tudo isso fica ao acaso. O aplicativo combina vocês pelas fotos, joga vocês em uma caixa de chat vazia e torce para que, de alguma forma, você vire sozinho um mestre em fazer perguntas. A ciência diz que perguntas e alternância constroem conexão — e o design te entrega uma tela em branco e um \"oi\"." },
    { type: "h2", accent: "green", text: "O Qulo coloca a pergunta dentro do primeiro contato" },
    { type: "p", text: "A mecânica central do Qulo começa exatamente onde a pesquisa aponta. Para dar match com alguém no Qulo, você não manda uma abertura fria — você responde **de 2 a 10 perguntas que a própria pessoa escreveu**. Seu primeiríssimo contato já é uma troca de perguntas e respostas de verdade sobre como você pensa e o que é importante para você. Aquele momento constrangedor do \"o que eu escrevo agora?\" desaparece, porque a conversa começa direto na substância, não no \"oi\"." },
    { type: "p", text: "Para ser claro: nenhum aplicativo pode prometer que uma ótima primeira troca vai virar um ótimo relacionamento — nenhuma leitura honesta da pesquisa sustenta essa afirmação. O que a pesquisa sustenta é algo mais restrito e mais útil: perguntas, autorrevelação e alternância são, de forma confiável, o caminho pelo qual desconhecidos começam a gostar um do outro. O Qulo simplesmente transforma essa dinâmica na porta de entrada, em vez de deixá-la ao acaso." },
    { type: "quote", text: "A melhor primeira mensagem nunca foi \"oi\". Sempre foi uma pergunta — uma que mostra que você realmente olhou, e que realmente se importa com a resposta." },
    { type: "h2", accent: "green", text: "Conclusão" },
    { type: "p", text: "Meio milhão de mensagens analisadas dizem que cumprimentos genéricos são ignorados. Os estudos sobre conversas de Harvard dizem que quem faz perguntas — especialmente perguntas de acompanhamento — é mais querido e consegue mais segundos encontros. E a psicologia experimental diz que é revezando perguntas e respostas que a proximidade realmente se forma. Se é assim que a conexão começa, por que deixá-la a cargo de uma caixa de chat vazia? O Qulo começa cada match com perguntas que valem a pena responder. Baixe o Qulo e comece sua próxima conversa onde a ciência diz que ela deve começar." },
  ],
  it: [
    { type: "p", text: "Avete fatto match. Hai scritto \"hey\". E poi… niente. Se questo copione ti suona familiare, il problema probabilmente non sei tu — è il messaggio. Il primo messaggio è uno dei momenti più misurati del dating online, e i dati di milioni di conversazioni puntano tutti nella stessa direzione: i saluti vengono ignorati, le domande ottengono risposte. Vale la pena capire la psicologia dietro questo divario, perché cambia il modo in cui inizi ogni conversazione — dentro e fuori dall'app." },
    { type: "h2", text: "I dati: \"hey\" è l'apertura peggiore su ogni app" },
    { type: "p", text: "Il team dati di OkCupid ha analizzato oltre 500.000 primi messaggi sulla piattaforma e ha scoperto che le aperture più comuni — \"hi\", \"hey\", \"hello\" — avevano tassi di risposta ben al di sotto della media, mentre i messaggi che agganciavano qualcosa di specifico andavano nettamente meglio. Il messaggio più generico possibile si è rivelato il meno efficace." },
    { type: "p", text: "Hinge ha condotto l'esperimento dall'altro lato: nel 2015 l'azienda ha testato per un mese circa 100 frasi di apertura diverse sulla propria base utenti. Il risultato è stato la stessa storia. Il classico \"hey, what's up?\" veniva regolarmente battuto dalle aperture che ponevano una domanda personalizzata o proponevano qualcosa di concreto. Originalità, specificità e una vera domanda a cui rispondere superavano un semplice saluto ogni volta." },
    { type: "h2", text: "La scoperta di Harvard: fare domande ti rende più simpatico" },
    { type: "p", text: "Non è solo una stranezza dei dati delle app. Nel 2017 Karen Huang, Michael Yeomans, Alison Wood Brooks, Julia Minson e Francesca Gino hanno pubblicato una serie di studi sul Journal of Personality and Social Psychology con un titolo memorabile: \"It Doesn't Hurt to Ask: Question-Asking Increases Liking\" (Chiedere non fa male: fare domande aumenta la simpatia). In conversazioni dal vivo tra sconosciuti, chi faceva più domande — soprattutto **domande di approfondimento**, quelle che si costruiscono su ciò che l'altra persona ha appena detto — risultava sistematicamente più gradito ai propri interlocutori." },
    { type: "p", text: "La parte più sorprendente è arrivata dal campo: i ricercatori hanno analizzato vere conversazioni di speed dating — 110 partecipanti, più di 2.000 appuntamenti. Chi faceva più domande di approfondimento aveva maggiori probabilità di ricevere un \"sì\" per un secondo appuntamento. Il terzo più attivo nel fare domande ha ricevuto il maggior numero di proposte per un secondo incontro. Fare domande non era solo cortesia: era misurabilmente attraente." },
    { type: "h2", text: "Perché funziona: una buona domanda è un regalo a doppio senso" },
    { type: "p", text: "Il meccanismo individuato dai ricercatori si chiama **responsiveness** (reattività): quando fai a qualcuno una domanda vera, segnali che stai ascoltando, che capisci e che ti importa. E rispondere fa genuinamente stare bene — gli psicologi sanno da tempo che l'auto-rivelazione, cioè parlare di sé a un ascoltatore interessato, è intrinsecamente piacevole. La persona che risponde attribuisce quel piacere a te, che hai fatto la domanda. Una buona domanda fa sentire interessante l'altra persona — e nel frattempo rende più simpatico te." },
    { type: "p", text: "C'è un ultimo ingrediente: l'alternanza. In uno studio del 2013 pubblicato sul Journal of Experimental Social Psychology, Susan Sprecher e colleghi hanno fatto conoscere degli sconosciuti in due modi: alternandosi nel fare e ricevere domande, oppure con una persona che si raccontava mentre l'altra si limitava ad ascoltare. Chi si alternava riportava livelli significativamente più alti di simpatia, vicinanza, somiglianza percepita e piacere. La connessione non nasce dalla performance di una sola persona; nasce dall'**alternarsi** — tu chiedi, io rispondo, io chiedo, tu rispondi." },
    { type: "h2", text: "Come iniziare una conversazione che ottiene davvero una risposta" },
    { type: "p", text: "Metti insieme i dati e la psicologia e il manuale si scrive da solo:" },
    { type: "ul", items: ["**Salta il saluto secco.** \"Hey\" (o \"ciao\") non dà all'altra persona nulla a cui rispondere — scarica tutto lo sforzo su di lei.", "**Chiedi di qualcosa di specifico.** Fai riferimento a un dettaglio che ha davvero condiviso; la specificità è la prova che hai prestato attenzione.", "**Rendila aperta.** Una domanda a cui si può rispondere con \"sì\" o \"no\" di solito riceverà proprio quello — e la conversazione muore lì.", "**Approfondisci la risposta.** Il segnale più forte emerso dalla ricerca non era la prima domanda ma la seconda — quella che dimostra che hai ascoltato."] },
    { type: "p", text: "C'è però un problema: sulla maggior parte delle app di dating tutto questo è lasciato al caso. L'app ti abbina in base alle foto, ti scarica in una chat vuota e spera che tu diventi da solo un abile intervistatore. La scienza dice che sono le domande e l'alternanza a costruire la connessione — e il design ti consegna uno schermo bianco e un \"hey\"." },
    { type: "h2", accent: "green", text: "Qulo integra la domanda nel primo contatto" },
    { type: "p", text: "La meccanica centrale di Qulo parte esattamente dal punto indicato dalla ricerca. Per fare match con qualcuno su Qulo non mandi un'apertura a freddo — rispondi a **2-10 domande scritte da quella persona stessa**. Il tuo primissimo contatto è già uno scambio di domande vere e risposte vere su come pensi e su cosa ti sta a cuore. Il momento imbarazzante del \"e adesso cosa scrivo?\" sparisce, perché la conversazione parte già nel vivo, non da un \"hey\"." },
    { type: "p", text: "Sia chiaro: nessuna app può promettere che un ottimo primo scambio diventi un'ottima relazione — nessuna lettura onesta della ricerca sostiene questa affermazione. Ciò che la ricerca sostiene è più circoscritto e più utile: domande, auto-rivelazione e alternanza sono il modo affidabile in cui due sconosciuti iniziano a piacersi. Qulo si limita a rendere questa dinamica il punto d'ingresso invece di lasciarla alla fortuna." },
    { type: "quote", text: "Il miglior primo messaggio non è mai stato \"hey\". È sempre stato una domanda — una che dimostra che hai davvero guardato, e che la risposta ti interessa davvero." },
    { type: "h2", accent: "green", text: "Conclusione" },
    { type: "p", text: "Mezzo milione di messaggi analizzati dice che i saluti generici vengono ignorati. Gli studi di Harvard sulla conversazione dicono che chi fa domande — soprattutto domande di approfondimento — è più apprezzato e ottiene più secondi appuntamenti. E la psicologia sperimentale dice che la vicinanza si costruisce alternandosi tra chiedere e rispondere. Se la connessione inizia così, perché lasciarla a una chat vuota? Qulo fa partire ogni match da domande a cui vale la pena rispondere. Scarica Qulo e inizia la tua prossima conversazione dal punto in cui la scienza dice che dovrebbe iniziare." },
  ],
  ja: [
    { type: "p", text: "マッチしました。「hey（やあ）」と送りました。そして……何も返ってこない。このループに見覚えがあるなら、問題はおそらくあなたではなく、メッセージのほうです。ファーストメッセージはオンラインデーティングの中でも最も徹底的に計測されてきた瞬間のひとつで、何百万もの会話データが指し示す方向はひとつ。挨拶は無視され、質問には答えが返ってくるのです。この差の背後にある心理学は知っておく価値があります。アプリの中でも外でも、あらゆる会話の始め方が変わるからです。" },
    { type: "h2", text: "データが示す事実──「hey」はどのアプリでも最悪のオープナー" },
    { type: "p", text: "OkCupidのデータチームは、プラットフォーム上の500,000件を超えるファーストメッセージを分析し、最もよく使われるオープナー──「hi」「hey」「hello」──の返信率が平均を大きく下回る一方、具体的な何かに触れたメッセージは目に見えて良い結果を出していることを発見しました。考えうる限り最も汎用的なメッセージが、最も効果のないメッセージだったのです。" },
    { type: "p", text: "Hingeは逆の側から実験を行いました。2015年、同社は約100種類の書き出しの文を1か月間、ユーザー全体でテストしたのです。結果は同じストーリーでした。定番の「hey, what's up?（やあ、元気？）」は、パーソナライズされた質問を投げかけたり具体的な提案をしたりするオープナーに一貫して負けたのです。新鮮さ、具体性、そして答えるべき本物の質問が、素っ気ない挨拶に毎回勝ちました。" },
    { type: "h2", text: "Harvardの発見──質問をする人は好かれる" },
    { type: "p", text: "これは単なるアプリデータ上の偶然ではありません。2017年、Karen Huang、Michael Yeomans、Alison Wood Brooks、Julia Minson、Francesca Ginoは、Journal of Personality and Social Psychologyに印象的なタイトルの一連の研究を発表しました。「It Doesn't Hurt to Ask: Question-Asking Increases Liking」（聞いて損はない──質問することは好意を高める）です。初対面の人同士の実際の会話において、より多くの質問をした人──特に相手が直前に言ったことを踏まえて掘り下げる**フォローアップの質問**をした人──は、会話の相手から一貫してより好かれていました。" },
    { type: "p", text: "最も印象的な部分は実地データから来ています。研究者たちは実際のスピードデーティングの会話──110人の参加者、2,000回を超えるデート──を分析しました。フォローアップの質問を多くした参加者ほど、2回目のデートへの「イエス」をもらえる確率が高かったのです。質問数で上位3分の1に入った人たちが、最も多くの2回目のデートのオファーを受け取りました。質問することは単なる礼儀ではなく、測定可能なほど魅力的だったのです。" },
    { type: "h2", text: "なぜ効くのか──良い質問は双方向の贈り物" },
    { type: "p", text: "研究者たちが特定したメカニズムは**応答性（レスポンシブネス）**と呼ばれるものです。相手に本物の質問をすると、あなたは「聞いています」「理解しています」「気にかけています」というシグナルを送ることになります。そして答えること自体が、実際に心地よいのです──関心を持って聞いてくれる相手に自分のことを話す「自己開示」がそれ自体で楽しいことは、心理学者が昔から知っている事実です。答える側はその心地よさを、質問したあなたに帰属させます。良い質問は相手に「自分は興味深い人間だ」と感じさせ、その過程であなた自身をより好かれる存在にするのです。" },
    { type: "p", text: "もうひとつ材料があります。交互にやりとりすることです。2013年にJournal of Experimental Social Psychologyに掲載された研究で、Susan Sprecherらは初対面の人同士に、交互に質問し答え合う形か、一方が話してもう一方はただ聞くだけの形か、いずれかで知り合ってもらいました。交互にやりとりした人たちは、好意、親密さ、類似性の認識、楽しさのすべてで有意に高いスコアを報告しました。つながりは一人が独演することからは生まれません。**交互に**やりとりすること──あなたが聞き、私が答え、私が聞き、あなたが答える──から生まれるのです。" },
    { type: "h2", text: "実際に返信がもらえる会話の始め方" },
    { type: "p", text: "データと心理学を組み合わせれば、やるべきことは自ずと見えてきます。" },
    { type: "ul", items: ["**素っ気ない挨拶はやめる。**「hey」は相手に答える材料を何も与えず、すべての労力を相手に丸投げしてしまいます。", "**具体的なことについて質問する。**相手が実際にシェアしたディテールに触れましょう。具体性は、ちゃんと見ていたことの証明です。", "**オープンエンドにする。**「はい」か「いいえ」で答えられる質問は、たいていそのとおりに答えられて──そこで会話が終わります。", "**答えに対してさらに質問する。**研究で最も強力なシグナルは最初の質問ではなく、2つ目の質問──ちゃんと聞いていたことを示す質問でした。"] },
    { type: "p", text: "ただし、落とし穴があります。ほとんどのデーティングアプリでは、これらすべてが運任せにされているのです。アプリは写真であなたをマッチさせ、空っぽのチャットボックスに放り込み、あなたがいつの間にか質問上手になることを祈るだけ。科学は「質問と交互のやりとりがつながりを築く」と言っているのに、アプリのデザインが与えてくれるのは真っ白な画面と「hey」なのです。" },
    { type: "h2", accent: "green", text: "Quloは最初のコンタクトに質問を組み込んでいる" },
    { type: "p", text: "Quloのコアメカニズムは、まさに研究が指し示す地点から始まります。Quloで誰かとマッチするには、そっけないオープナーを送るのではなく、**その人が自分で書いた2〜10問の質問**に答えるのです。最初のコンタクトの時点で、あなたの考え方や大切にしていることをめぐる、本物の質問と本物の答えのやりとりが始まっています。あの気まずい「何て送ればいいんだろう？」という瞬間は消えます。会話は「hey」からではなく、いきなり中身から始まるからです。" },
    { type: "p", text: "はっきりさせておきましょう。素晴らしい最初のやりとりが素晴らしい関係につながると約束できるアプリはありません──研究を誠実に読む限り、そんな主張を支持するものはないのです。研究が支持しているのは、もっと限定的で、もっと実用的なこと。質問、自己開示、交互のやりとりこそが、初対面の人同士が互いに好意を持ち始める確かな道筋だということです。Quloはそのダイナミクスを運任せにせず、入り口そのものにしているだけなのです。" },
    { type: "quote", text: "最高のファーストメッセージは、決して「hey」ではありませんでした。それはいつだって質問──あなたがちゃんと見ていて、答えを本気で気にかけていることを示す質問だったのです。" },
    { type: "h2", accent: "green", text: "まとめ" },
    { type: "p", text: "分析された50万件のメッセージは、汎用的な挨拶は無視されると告げています。Harvardの会話研究は、質問をする人──特にフォローアップの質問をする人──のほうが好かれ、2回目のデートにも多くつながると告げています。そして実験心理学は、親密さは交互に質問し答え合うことで築かれると告げています。つながりがそうやって始まるものなら、なぜそれを空っぽのチャットボックスに委ねるのでしょう？Quloはすべてのマッチを、答える価値のある質問から始めます。Quloをダウンロードして、次の会話を科学が指し示す場所から始めましょう。" },
  ],
  ko: [
    { type: "p", text: "매칭이 됐습니다. \"안녕(hey)\"이라고 보냈습니다. 그리고… 아무 일도 일어나지 않았죠. 이 패턴이 익숙하게 느껴진다면, 문제는 아마 당신이 아니라 메시지에 있습니다. 첫 메시지는 온라인 데이팅에서 가장 많이 측정되는 순간 중 하나이며, 수백만 건의 대화 데이터는 한 방향을 가리킵니다: 인사말은 무시당하고, 질문은 답을 받습니다. 이 차이 뒤에 숨은 심리를 이해할 가치는 충분합니다. 앱 안에서든 밖에서든, 모든 대화를 시작하는 방식이 달라지기 때문입니다." },
    { type: "h2", text: "데이터가 말합니다: \"Hey\"는 모든 앱에서 최악의 오프너입니다" },
    { type: "p", text: "OkCupid의 데이터 팀은 플랫폼에서 오간 500,000건 이상의 첫 메시지를 분석했고, 가장 흔한 오프너인 \"hi\", \"hey\", \"hello\"의 답장률이 평균을 크게 밑도는 반면, 구체적인 무언가를 언급한 메시지는 눈에 띄게 좋은 성과를 낸다는 사실을 발견했습니다. 가장 뻔한 메시지가 가장 효과 없는 메시지로 드러난 것입니다." },
    { type: "p", text: "Hinge는 반대편에서 같은 실험을 했습니다. 2015년, 이 회사는 약 100가지 오프닝 문구를 한 달 동안 전체 사용자에게 테스트했습니다. 결과는 같은 이야기였습니다. 고전적인 \"hey, what's up?\"은 개인화된 질문을 던지거나 구체적인 무언가를 제안하는 오프너에 매번 밀렸습니다. 참신함, 구체성, 그리고 실제로 답할 수 있는 질문이 밋밋한 인사를 언제나 이겼습니다." },
    { type: "h2", text: "하버드의 발견: 질문을 하면 호감을 얻습니다" },
    { type: "p", text: "이것은 단순한 앱 데이터의 우연이 아닙니다. 2017년 Karen Huang, Michael Yeomans, Alison Wood Brooks, Julia Minson, Francesca Gino는 Journal of Personality and Social Psychology에 인상적인 제목의 연구 시리즈를 발표했습니다: \"It Doesn't Hurt to Ask: Question-Asking Increases Liking\"(물어봐서 손해 볼 것 없다: 질문하기는 호감을 높인다). 낯선 사람들 사이의 실제 대화에서, 질문을 더 많이 한 사람 — 특히 상대가 방금 한 말 위에 쌓아 올리는 **후속 질문**을 한 사람 — 은 대화 상대에게 일관되게 더 큰 호감을 얻었습니다." },
    { type: "p", text: "가장 인상적인 부분은 현장에서 나왔습니다. 연구진은 실제 스피드 데이팅 대화를 분석했습니다 — 참가자 110명, 2,000회가 넘는 데이트. 후속 질문을 더 많이 한 참가자는 두 번째 데이트에 \"예스\"를 받을 확률이 더 높았습니다. 질문을 가장 많이 한 상위 3분의 1이 두 번째 데이트 제안을 가장 많이 받았습니다. 질문은 단순한 예의가 아니라, 측정 가능할 만큼 매력적이었습니다." },
    { type: "h2", text: "왜 효과가 있을까: 좋은 질문은 양방향 선물입니다" },
    { type: "p", text: "연구진이 밝혀낸 메커니즘의 이름은 **반응성**(responsiveness)입니다. 누군가에게 진짜 질문을 던지면, 당신이 듣고 있고, 이해하고 있고, 관심을 갖고 있다는 신호를 보내는 셈입니다. 그리고 답하는 것 자체가 정말로 기분 좋은 일입니다 — 관심 있는 청자에게 자기 이야기를 하는 것, 즉 자기개방이 본질적으로 즐겁다는 사실을 심리학자들은 오래전부터 알고 있었습니다. 답하는 사람은 그 즐거움을 질문한 사람, 즉 당신에게 돌립니다. 좋은 질문은 상대방이 스스로를 흥미로운 사람이라고 느끼게 하고 — 그 과정에서 당신을 더 호감 가는 사람으로 만듭니다." },
    { type: "p", text: "재료가 하나 더 있습니다: 주고받기입니다. Susan Sprecher와 동료들이 2013년 Journal of Experimental Social Psychology에 발표한 연구에서, 낯선 사람들은 번갈아 가며 질문하고 답하거나, 한 사람만 이야기하고 다른 사람은 듣기만 하는 방식으로 서로를 알아갔습니다. 번갈아 주고받은 쪽이 호감, 친밀감, 유사성 인식, 즐거움 모두에서 유의미하게 높은 점수를 보고했습니다. 연결은 한 사람의 퍼포먼스에서 오지 않습니다. **번갈아 가는 것**에서 옵니다 — 당신이 묻고, 내가 답하고, 내가 묻고, 당신이 답하는 것." },
    { type: "h2", text: "실제로 답장을 받는 대화, 이렇게 시작하세요" },
    { type: "p", text: "데이터와 심리학을 나란히 놓으면 전략은 저절로 완성됩니다:" },
    { type: "ul", items: ["**밋밋한 인사는 건너뛰세요.** \"안녕\"은 상대에게 답할 거리를 아무것도 주지 않습니다 — 모든 수고를 상대에게 떠넘기는 셈입니다.", "**구체적인 것에 대해 물어보세요.** 상대가 실제로 공개한 디테일을 언급하세요. 구체성은 당신이 관심을 기울였다는 증거입니다.", "**열린 질문으로 만드세요.** \"네\"나 \"아니요\"로 답할 수 있는 질문은 대개 그렇게 답이 돌아오고 — 대화는 거기서 끝납니다.", "**답변에 이어서 다시 물어보세요.** 연구에서 가장 강력한 신호는 첫 번째 질문이 아니라 두 번째 질문이었습니다 — 당신이 들었다는 것을 보여주는 질문 말입니다."] },
    { type: "p", text: "하지만 문제가 하나 있습니다. 대부분의 데이팅 앱에서는 이 모든 것이 운에 맡겨져 있습니다. 앱은 사진으로 당신을 매칭하고, 빈 채팅창에 던져 놓은 뒤, 당신이 알아서 능숙한 질문가가 되기를 바랍니다. 과학은 질문과 주고받기가 연결을 만든다고 말하는데, 앱의 디자인은 빈 화면과 \"안녕\" 하나를 건넬 뿐입니다." },
    { type: "h2", accent: "green", text: "Qulo는 첫 만남 자체에 질문을 심어 놓았습니다" },
    { type: "p", text: "Qulo의 핵심 메커니즘은 연구가 가리키는 바로 그 지점에서 시작합니다. Qulo에서 누군가와 매칭되려면 어색한 첫 메시지를 보내는 것이 아니라, **그 사람이 직접 만든 2-10개의 질문**에 답합니다. 당신의 첫 접촉 자체가 이미, 당신이 어떻게 생각하고 무엇을 소중히 여기는지에 대한 진짜 질문과 진짜 답변의 교환인 것입니다. \"대체 뭐라고 보내지?\"라는 어색한 순간은 사라집니다. 대화가 \"안녕\"이 아니라 알맹이 한가운데서 시작되기 때문입니다." },
    { type: "p", text: "분명히 해 둘 것이 있습니다. 훌륭한 첫 대화가 훌륭한 관계로 이어진다고 약속할 수 있는 앱은 없습니다 — 연구를 정직하게 읽는다면 그런 주장은 성립하지 않습니다. 연구가 뒷받침하는 것은 더 좁고 더 유용한 사실입니다: 질문, 자기개방, 그리고 주고받기는 낯선 사람들이 서로에게 호감을 느끼기 시작하는 검증된 방식이라는 것. Qulo는 그 역동을 운에 맡기는 대신, 만남의 출발점으로 만들었을 뿐입니다." },
    { type: "quote", text: "최고의 첫 메시지는 한 번도 \"안녕\"이었던 적이 없습니다. 언제나 질문이었습니다 — 당신이 정말로 들여다봤고, 그 답을 정말로 궁금해한다는 것을 보여주는 질문." },
    { type: "h2", accent: "green", text: "결론" },
    { type: "p", text: "분석된 50만 건의 메시지는 뻔한 인사말이 무시당한다고 말합니다. 하버드의 대화 연구는 질문하는 사람 — 특히 후속 질문을 하는 사람 — 이 더 큰 호감을 얻고 두 번째 데이트도 더 많이 얻는다고 말합니다. 그리고 실험심리학은 번갈아 묻고 답하는 것이 친밀감이 실제로 만들어지는 방식이라고 말합니다. 연결이 그렇게 시작된다면, 왜 그것을 빈 채팅창에 맡겨 두시겠습니까? Qulo는 모든 매칭을 답할 가치가 있는 질문으로 시작합니다. Qulo를 다운로드하고, 다음 대화를 과학이 가리키는 지점에서 시작해 보세요." },
  ],
  zh: [
    { type: "p", text: "你们配对成功了。你打出了一句「嗨」。然后……没有然后了。如果这个循环听起来很熟悉，问题很可能不在你身上——而在那条消息上。第一条消息是在线交友中被测量得最充分的时刻之一，来自数百万段对话的数据都指向同一个方向：打招呼会被无视，提问才会得到回答。这条鸿沟背后的心理学值得弄明白，因为它会改变你开启每一段对话的方式——无论在应用里还是在现实中。" },
    { type: "h2", text: "数据说话：「嗨」是所有应用上最糟糕的开场白" },
    { type: "p", text: "OkCupid 的数据团队分析了平台上超过 500,000 条第一条消息，发现最常见的开场白——「hi」「hey」「hello」——回复率远低于平均水平，而那些针对具体内容展开的消息表现明显更好。最泛泛的那条消息，恰恰是最没有效果的一条。" },
    { type: "p", text: "Hinge 从另一个方向做了这个实验：2015 年，该公司在其用户群中测试了大约 100 种不同的开场白，持续一个月。结果讲的是同一个故事。经典的「hey, what's up?」（嗨，最近怎么样？）总是输给那些提出个性化问题或给出具体提议的开场白。新颖、具体、外加一个真正需要回答的问题，每一次都胜过一句干巴巴的问候。" },
    { type: "h2", text: "哈佛的发现：提问会让人更喜欢你" },
    { type: "p", text: "这不只是应用数据里的偶然现象。2017 年，Karen Huang、Michael Yeomans、Alison Wood Brooks、Julia Minson 和 Francesca Gino 在 Journal of Personality and Social Psychology 上发表了一系列研究，标题令人过目不忘：\"It Doesn't Hurt to Ask: Question-Asking Increases Liking\"（问一问无妨：提问会增加好感）。在陌生人之间的真实对话中，提问更多的人——尤其是提出**追问**、也就是顺着对方刚说的话继续深挖的人——始终更受对话伙伴的喜欢。" },
    { type: "p", text: "最惊人的部分来自实地研究：研究者分析了真实的快速约会对话——110 位参与者，超过 2,000 次约会。提出更多追问的快速约会者，更有可能获得对方对第二次约会说「愿意」。提问最多的那三分之一，收到的二次约会邀请也最多。提问不只是礼貌，它是可测量的吸引力。" },
    { type: "h2", text: "为什么有效：一个好问题是一份双向的礼物" },
    { type: "p", text: "研究者找到的机制叫**回应性**（responsiveness）：当你向某人提出一个真正的问题时，你是在传递信号——你在倾听，你能理解，你在乎。而回答本身就令人愉悦——心理学家早就知道，向一位感兴趣的倾听者敞开自己（自我表露）本身就是享受。回答的人会把这份愉悦归功于你这个提问者。一个好问题会让对方觉得自己很有趣——同时也让你在这个过程中更招人喜欢。" },
    { type: "p", text: "还有一味关键的配料：轮流。在 2013 年发表于 Journal of Experimental Social Psychology 的一项研究中，Susan Sprecher 及其同事让陌生人以两种方式相识：要么轮流提问和回答，要么由一个人倾诉、另一个人只负责倾听。轮流交谈的那组报告了显著更高的好感、亲近感、相似感和愉悦感。连结不是靠一个人的独角戏建立的，而是来自**你来我往**——你问，我答；我问，你答。" },
    { type: "h2", text: "如何开启一段真正能得到回复的对话" },
    { type: "p", text: "把数据和心理学放在一起，行动指南自己就写出来了：" },
    { type: "ul", items: ["**跳过干巴巴的问候。**一句「嗨」没有给对方任何可以回答的东西——它把所有的功课都甩给了对方。", "**针对具体的事情提问。**提到对方真正分享过的一个细节；具体本身就是你用心看过的证明。", "**把问题问成开放式的。**一个能用「是」或「不是」回答的问题，通常就会被那样回答——对话也就死在了那里。", "**顺着答案追问。**研究中最强的信号不是第一个问题，而是第二个——那个证明你认真听了的问题。"] },
    { type: "p", text: "但问题来了：在大多数交友应用里，这一切全靠运气。应用根据照片给你配对，把你丢进一个空空的聊天框，然后指望你自己莫名其妙地变成一位提问高手。科学说，是提问和轮流交谈建立了连结——而产品设计给你的，却是一块空白屏幕和一句「嗨」。" },
    { type: "h2", accent: "green", text: "Qulo 把提问内置进了第一次接触" },
    { type: "p", text: "Qulo 的核心机制正是从研究所指向的地方开始的。想在 Qulo 上与某人配对，你不用发一条冷冰冰的开场白——你要回答**对方亲手写下的 2-10 个问题**。你们的第一次接触，从一开始就是围绕彼此如何思考、在乎什么而展开的真实问答交流。那个尴尬的「我到底该说点什么？」的瞬间不复存在，因为对话不是从「嗨」开始的，而是直接从实质内容开始的。" },
    { type: "p", text: "有一点必须说清楚：没有任何应用能承诺一次精彩的初次交流会变成一段精彩的感情——对研究的任何诚实解读都支撑不了这种说法。研究真正支持的结论更窄、也更有用：提问、自我表露和轮流交谈，是陌生人开始喜欢彼此的可靠途径。Qulo 只是把这种动力变成了入口，而不是把它交给运气。" },
    { type: "quote", text: "最好的第一条消息从来都不是「嗨」。它永远是一个问题——一个证明你真的看过、也真的在乎答案的问题。" },
    { type: "h2", accent: "green", text: "结语" },
    { type: "p", text: "五十万条被分析过的消息告诉我们：千篇一律的问候会被无视。哈佛的对话研究告诉我们：爱提问的人——尤其是会追问的人——更受喜欢，也能获得更多第二次约会。而实验心理学告诉我们：亲近感正是在你问我答的轮流中建立起来的。既然连结是这样开始的，为什么要把它交给一个空白的聊天框？Qulo 让每一次配对都从值得回答的问题开始。下载 Qulo，让你的下一段对话从科学指明的地方开始。" },
  ],
  nl: [
    { type: "p", text: "Jullie hebben een match. Je typte \"hey\". En toen… niets. Als deze lus je bekend voorkomt, ligt het probleem waarschijnlijk niet aan jou — maar aan het bericht. Eerste berichten behoren tot de meest gemeten momenten in online dating, en de data van miljoenen gesprekken wijzen in één richting: begroetingen worden genegeerd, vragen krijgen antwoord. De psychologie achter dat verschil is de moeite waard om te begrijpen, want ze verandert hoe je elk gesprek begint — op een app of daarbuiten." },
    { type: "h2", text: "De data: \"hey\" is de slechtste opener op elke app" },
    { type: "p", text: "Het datateam van OkCupid analyseerde meer dan 500.000 eerste berichten op het platform en ontdekte dat de meest voorkomende openers — \"hi\", \"hey\", \"hello\" — antwoordpercentages hadden die ruim onder het gemiddelde lagen, terwijl berichten die op iets specifieks ingingen het duidelijk beter deden. Het meest generieke bericht dat je kunt sturen bleek het minst effectieve te zijn." },
    { type: "p", text: "Hinge voerde het experiment vanaf de andere kant uit: in 2015 testte het bedrijf een maand lang zo'n 100 verschillende openingszinnen onder zijn gebruikers. Het resultaat was hetzelfde verhaal. Het klassieke \"hey, what's up?\" werd stelselmatig verslagen door openers die een gepersonaliseerde vraag stelden of iets concreets voorstelden. Originaliteit, specificiteit en een echte vraag om te beantwoorden wonnen het elke keer van een kale begroeting." },
    { type: "h2", text: "De Harvard-bevinding: vragen stellen maakt je sympathieker" },
    { type: "p", text: "Dit is niet zomaar een eigenaardigheid van app-data. In 2017 publiceerden Karen Huang, Michael Yeomans, Alison Wood Brooks, Julia Minson en Francesca Gino een reeks studies in de Journal of Personality and Social Psychology onder een gedenkwaardige titel: \"It Doesn't Hurt to Ask: Question-Asking Increases Liking\" (Vragen staat vrij: vragen stellen vergroot de sympathie). In live gesprekken tussen vreemden werden mensen die meer vragen stelden — vooral **vervolgvragen**, de vragen die voortbouwen op wat de ander net zei — door hun gesprekspartners consequent sympathieker gevonden." },
    { type: "p", text: "Het meest opvallende deel kwam uit het veld: de onderzoekers analyseerden echte speeddate-gesprekken — 110 daters, meer dan 2.000 dates. Speeddaters die meer vervolgvragen stelden, kregen vaker een \"ja\" op een tweede date. Het derde deel dat de meeste vragen stelde, ontving de meeste uitnodigingen voor een tweede date. Vragen stellen was niet alleen beleefd; het was meetbaar aantrekkelijk." },
    { type: "h2", text: "Waarom het werkt: een goede vraag is een geschenk voor twee" },
    { type: "p", text: "Het mechanisme dat de onderzoekers identificeerden heet **responsiviteit**: als je iemand een echte vraag stelt, laat je zien dat je luistert, dat je het begrijpt en dat het je iets kan schelen. En antwoorden voelt oprecht goed — psychologen weten al lang dat zelfonthulling, over jezelf praten tegen een geïnteresseerde luisteraar, van nature plezierig is. Degene die antwoordt, schrijft dat plezier toe aan jou, de vraagsteller. Een goede vraag laat de ander zich interessant voelen — en maakt jou onderweg sympathieker." },
    { type: "p", text: "Er is nog één ingrediënt: om de beurt. In een studie uit 2013 in de Journal of Experimental Social Psychology lieten Susan Sprecher en collega's vreemden kennismaken door ofwel om de beurt vragen te stellen en te beantwoorden, ofwel doordat één persoon vertelde terwijl de ander alleen luisterde. De beurtwisselaars rapporteerden significant meer sympathie, verbondenheid, ervaren gelijkenis en plezier. Verbinding ontstaat niet doordat één persoon een show opvoert; ze ontstaat door **afwisselen** — jij vraagt, ik antwoord, ik vraag, jij antwoordt." },
    { type: "h2", text: "Zo begin je een gesprek dat echt antwoord krijgt" },
    { type: "p", text: "Leg de data en de psychologie naast elkaar en het draaiboek schrijft zichzelf:" },
    { type: "ul", items: ["**Sla de kale begroeting over.** \"Hey\" geeft de ander niets om op te antwoorden — het schuift al het werk naar hem of haar door.", "**Vraag naar iets specifieks.** Verwijs naar een detail dat de ander echt heeft gedeeld; specificiteit is het bewijs dat je hebt opgelet.", "**Maak de vraag open.** Een vraag die met \"ja\" of \"nee\" beantwoord kan worden, wordt dat meestal ook — en daar sterft het gesprek.", "**Stel een vervolgvraag op het antwoord.** Het sterkste signaal in het onderzoek was niet de eerste vraag, maar de tweede — de vraag die laat zien dat je hebt geluisterd."] },
    { type: "p", text: "Maar hier zit het addertje: op de meeste datingapps wordt dit allemaal aan het toeval overgelaten. De app matcht je op foto's, zet je in een leeg chatvenster en hoopt dat je op eigen kracht een bedreven vraagsteller wordt. De wetenschap zegt dat vragen en beurtwisseling verbinding opbouwen — en het ontwerp geeft je een leeg scherm en een \"hey\"." },
    { type: "h2", accent: "green", text: "Qulo bouwt de vraag in het eerste contact in" },
    { type: "p", text: "Het kernmechanisme van Qulo begint precies waar het onderzoek naar wijst. Om op Qulo met iemand te matchen stuur je geen koude opener — je beantwoordt **2-10 vragen die die persoon zelf heeft geschreven**. Je allereerste contact is al een uitwisseling van echte vragen en echte antwoorden over hoe je denkt en wat je belangrijk vindt. Het ongemakkelijke \"wat moet ik in vredesnaam zeggen?\"-moment is verdwenen, omdat het gesprek midden in de inhoud begint, niet bij \"hey\"." },
    { type: "p", text: "Voor de duidelijkheid: geen enkele app kan beloven dat een geweldige eerste uitwisseling een geweldige relatie wordt — geen eerlijke lezing van het onderzoek ondersteunt die claim. Wat het onderzoek wél ondersteunt is smaller en nuttiger: vragen, zelfonthulling en beurtwisseling zijn betrouwbaar de manier waarop vreemden elkaar aardig beginnen te vinden. Qulo maakt van die dynamiek simpelweg het startpunt in plaats van het aan het toeval over te laten." },
    { type: "quote", text: "Het beste eerste bericht was nooit \"hey\". Het was altijd een vraag — een vraag die laat zien dat je echt hebt gekeken, en echt om het antwoord geeft." },
    { type: "h2", accent: "green", text: "Conclusie" },
    { type: "p", text: "Een half miljoen geanalyseerde berichten zeggen dat generieke begroetingen worden genegeerd. De gespreksstudies van Harvard zeggen dat vraagstellers — vooral zij die vervolgvragen stellen — sympathieker worden gevonden en meer tweede dates krijgen. En de experimentele psychologie zegt dat verbondenheid ontstaat door om de beurt te vragen en te antwoorden. Als verbinding zo begint, waarom zou je het dan aan een leeg chatvenster overlaten? Qulo begint elke match met vragen die het beantwoorden waard zijn. Download Qulo en begin je volgende gesprek waar de wetenschap zegt dat het moet beginnen." },
  ],
  pl: [
    { type: "p", text: "Dopasowaliście się. Napisałeś „hej”. A potem… nic. Jeśli ta pętla brzmi znajomo, problem prawdopodobnie nie leży w Tobie — tylko w wiadomości. Pierwsze wiadomości to jeden z najdokładniej mierzonych momentów w randkowaniu online, a dane z milionów rozmów wskazują w jednym kierunku: powitania są ignorowane, pytania dostają odpowiedzi. Warto zrozumieć psychologię stojącą za tą różnicą, bo zmienia ona sposób, w jaki zaczynasz każdą rozmowę — w aplikacji i poza nią." },
    { type: "h2", text: "Dane: „hej” to najgorszy początek w każdej aplikacji" },
    { type: "p", text: "Zespół danych OkCupid przeanalizował ponad 500 000 pierwszych wiadomości na platformie i odkrył, że najczęstsze otwarcia — „hi”, „hey”, „hello” — miały wskaźniki odpowiedzi wyraźnie poniżej średniej, podczas gdy wiadomości nawiązujące do czegoś konkretnego wypadały znacząco lepiej. Najbardziej generyczna z możliwych wiadomości okazała się najmniej skuteczna." },
    { type: "p", text: "Hinge przeprowadził ten eksperyment z drugiej strony: w 2015 roku firma przez miesiąc testowała około 100 różnych zdań otwierających na swojej bazie użytkowników. Wynik opowiadał tę samą historię. Klasyczne „hey, what's up?” („hej, co słychać?”) konsekwentnie przegrywało z otwarciami, które zadawały spersonalizowane pytanie albo proponowały coś konkretnego. Oryginalność, konkret i prawdziwe pytanie, na które da się odpowiedzieć, za każdym razem pokonywały suche powitanie." },
    { type: "h2", text: "Odkrycie z Harvardu: zadawanie pytań sprawia, że ludzie Cię lubią" },
    { type: "p", text: "To nie jest tylko ciekawostka z danych aplikacji. W 2017 roku Karen Huang, Michael Yeomans, Alison Wood Brooks, Julia Minson i Francesca Gino opublikowali w Journal of Personality and Social Psychology serię badań pod zapadającym w pamięć tytułem: „It Doesn't Hurt to Ask: Question-Asking Increases Liking” (Zapytać nie zaszkodzi: zadawanie pytań zwiększa sympatię). W rozmowach na żywo między nieznajomymi osoby, które zadawały więcej pytań — zwłaszcza **pytań pogłębiających**, czyli takich, które nawiązują do tego, co druga osoba właśnie powiedziała — były konsekwentnie bardziej lubiane przez swoich rozmówców." },
    { type: "p", text: "Najbardziej uderzająca część pochodziła z terenu: badacze przeanalizowali prawdziwe rozmowy podczas speed datingu — 110 uczestników, ponad 2000 randek. Uczestnicy speed datingu, którzy zadawali więcej pytań pogłębiających, częściej słyszeli „tak” w sprawie drugiej randki. Górna jedna trzecia najczęściej pytających otrzymała najwięcej propozycji drugiej randki. Pytanie nie było tylko uprzejme — było mierzalnie atrakcyjne." },
    { type: "h2", text: "Dlaczego to działa: dobre pytanie to prezent dla obu stron" },
    { type: "p", text: "Mechanizm zidentyfikowany przez badaczy nazywa się **responsywnością**: gdy zadajesz komuś prawdziwe pytanie, sygnalizujesz, że słuchasz, że rozumiesz i że Ci zależy. A odpowiadanie naprawdę sprawia przyjemność — psycholodzy od dawna wiedzą, że autoprezentacja, czyli opowiadanie o sobie zainteresowanemu słuchaczowi, jest z natury przyjemna. Osoba odpowiadająca przypisuje tę przyjemność Tobie — temu, kto zapytał. Dobre pytanie sprawia, że druga osoba czuje się interesująca — a Ciebie przy okazji czyni bardziej lubianym." },
    { type: "p", text: "Jest jeszcze jeden składnik: naprzemienność. W badaniu z 2013 roku opublikowanym w Journal of Experimental Social Psychology Susan Sprecher ze współpracownikami poprosiła nieznajomych, by poznali się albo zadając sobie pytania i odpowiadając na nie na zmianę, albo tak, że jedna osoba opowiadała o sobie, a druga tylko słuchała. Ci, którzy rozmawiali na zmianę, deklarowali istotnie więcej sympatii, bliskości, poczucia podobieństwa i przyjemności. Więź nie rodzi się z występu jednej osoby; rodzi się z **naprzemienności** — Ty pytasz, ja odpowiadam, ja pytam, Ty odpowiadasz." },
    { type: "h2", text: "Jak zacząć rozmowę, która naprawdę dostanie odpowiedź" },
    { type: "p", text: "Zestaw dane z psychologią, a podręcznik napisze się sam:" },
    { type: "ul", items: ["**Odpuść suche powitanie.** „Hej” nie daje drugiej osobie nic, na co można odpowiedzieć — cały wysiłek przerzuca na nią.", "**Zapytaj o coś konkretnego.** Nawiąż do szczegółu, którym ta osoba naprawdę się podzieliła; konkret to dowód, że zwróciłeś uwagę.", "**Zadawaj pytania otwarte.** Na pytanie, na które da się odpowiedzieć „tak” lub „nie”, zwykle właśnie tak pada odpowiedź — i rozmowa na tym umiera.", "**Dopytaj o odpowiedź.** Najsilniejszym sygnałem w badaniach nie było pierwsze pytanie, lecz drugie — to, które pokazuje, że słuchałeś."] },
    { type: "p", text: "Jest jednak haczyk: w większości aplikacji randkowych wszystko to pozostawione jest przypadkowi. Aplikacja dopasowuje Was na podstawie zdjęć, wrzuca do pustego okna czatu i liczy, że jakoś sam z siebie staniesz się mistrzem zadawania pytań. Nauka mówi, że więź budują pytania i naprzemienność — a projekt aplikacji daje Ci pusty ekran i „hej”." },
    { type: "h2", accent: "green", text: "Qulo wbudowuje pytanie w pierwszy kontakt" },
    { type: "p", text: "Kluczowa mechanika Qulo zaczyna się dokładnie tam, gdzie wskazują badania. Aby dopasować się z kimś w Qulo, nie wysyłasz zimnego otwarcia — odpowiadasz na **2-10 pytań, które ta osoba sama napisała**. Twój pierwszy kontakt to już wymiana prawdziwych pytań i prawdziwych odpowiedzi o tym, jak myślisz i co jest dla Ciebie ważne. Ten niezręczny moment „co ja mam w ogóle napisać?” znika, bo rozmowa zaczyna się od konkretów, a nie od „hej”." },
    { type: "p", text: "Powiedzmy jasno: żadna aplikacja nie może obiecać, że świetna pierwsza wymiana zamieni się w świetny związek — żadne uczciwe odczytanie badań nie potwierdza takiej tezy. To, co badania faktycznie potwierdzają, jest węższe i bardziej użyteczne: pytania, otwieranie się i naprzemienność to niezawodny sposób, w jaki nieznajomi zaczynają się lubić. Qulo po prostu czyni tę dynamikę punktem wejścia, zamiast zostawiać ją przypadkowi." },
    { type: "quote", text: "Najlepszą pierwszą wiadomością nigdy nie było „hej”. Zawsze było nią pytanie — takie, które pokazuje, że naprawdę się przyjrzałeś i naprawdę zależy Ci na odpowiedzi." },
    { type: "h2", accent: "green", text: "Podsumowanie" },
    { type: "p", text: "Pół miliona przeanalizowanych wiadomości mówi, że generyczne powitania są ignorowane. Harwardzkie badania nad rozmową mówią, że osoby zadające pytania — zwłaszcza pogłębiające — są bardziej lubiane i dostają więcej drugich randek. A psychologia eksperymentalna mówi, że bliskość rodzi się właśnie z pytania i odpowiadania na zmianę. Skoro tak zaczyna się więź, po co zostawiać ją pustemu oknu czatu? Qulo zaczyna każde dopasowanie od pytań wartych odpowiedzi. Pobierz Qulo i zacznij swoją następną rozmowę tam, gdzie według nauki powinna się zacząć." },
  ],
  sv: [
    { type: "p", text: "Ni matchade. Du skrev \"hej\". Och sedan… ingenting. Om den här loopen känns bekant är problemet förmodligen inte du — det är meddelandet. Första meddelanden är ett av de mest noggrant uppmätta ögonblicken inom nätdejting, och data från miljontals konversationer pekar åt ett och samma håll: hälsningar ignoreras, frågor får svar. Psykologin bakom det gapet är värd att förstå, för den förändrar hur du inleder varje samtal — i en app eller utanför den." },
    { type: "h2", text: "Datan: \"hej\" är den sämsta öppningen i varje app" },
    { type: "p", text: "OkCupids dataavdelning analyserade över 500,000 första meddelanden på plattformen och fann att de vanligaste öppningarna — \"hi\", \"hey\", \"hello\" — hade svarsfrekvenser långt under genomsnittet, medan meddelanden som knöt an till något specifikt gick märkbart bättre. Det mest generiska meddelande som går att skriva visade sig vara det minst effektiva." },
    { type: "p", text: "Hinge körde experimentet från andra hållet: 2015 testade företaget runt 100 olika öppningsrepliker på sina användare under en månad. Resultatet blev samma historia. Det klassiska \"hey, what's up?\" (\"tja, läget?\") blev konsekvent slaget av öppningar som ställde en personlig fråga eller föreslog något konkret. Nytänkande, specificitet och en faktisk fråga att besvara vann över en naken hälsning varje gång." },
    { type: "h2", text: "Harvard-fyndet: att ställa frågor gör dig omtyckt" },
    { type: "p", text: "Det här är inte bara en egenhet i appdata. 2017 publicerade Karen Huang, Michael Yeomans, Alison Wood Brooks, Julia Minson och Francesca Gino en serie studier i Journal of Personality and Social Psychology under en minnesvärd titel: \"It Doesn't Hurt to Ask: Question-Asking Increases Liking\" (Det skadar inte att fråga: att ställa frågor ökar omtyckthet). I livesamtal mellan främlingar blev de som ställde fler frågor — särskilt **följdfrågor**, de som bygger vidare på vad den andra just sagt — konsekvent mer omtyckta av sina samtalspartner." },
    { type: "p", text: "Det mest slående kom från fältet: forskarna analyserade verkliga speeddejting-samtal — 110 dejtare, fler än 2,000 dejter. Speeddejtare som ställde fler följdfrågor fick oftare ett \"ja\" till en andra dejt. Den tredjedel som ställde flest frågor fick flest erbjudanden om en andra dejt. Att fråga var inte bara artigt — det var mätbart attraktivt." },
    { type: "h2", text: "Därför fungerar det: en bra fråga är en gåva åt båda hållen" },
    { type: "p", text: "Mekanismen forskarna identifierade kallas **responsivitet**: när du ställer en riktig fråga signalerar du att du lyssnar, att du förstår och att du bryr dig. Och att svara känns genuint bra — psykologer har länge vetat att självutlämnande, att berätta om sig själv för en intresserad lyssnare, är njutbart i sig. Personen som svarar tillskriver den känslan dig, den som frågade. En bra fråga får den andra att känna sig intressant — och gör dig mer omtyckt på köpet." },
    { type: "p", text: "Det finns en ingrediens till: turtagning. I en studie från 2013 i Journal of Experimental Social Psychology lät Susan Sprecher och hennes kollegor främlingar lära känna varandra antingen genom att turas om att fråga och svara, eller genom att en person berättade om sig själv medan den andra bara lyssnade. De som turades om rapporterade betydligt mer omtyckthet, närhet, upplevd likhet och glädje. Kontakt uppstår inte när en person uppträder; den uppstår genom att **växla** — du frågar, jag svarar, jag frågar, du svarar." },
    { type: "h2", text: "Så inleder du ett samtal som faktiskt får svar" },
    { type: "p", text: "Lägg ihop datan och psykologin, så skriver spelboken sig själv:" },
    { type: "ul", items: ["**Hoppa över den nakna hälsningen.** \"Hej\" ger den andra ingenting att svara på — det lämpar över hela ansträngningen på hen.", "**Fråga om något specifikt.** Knyt an till en detalj personen faktiskt delat med sig av; specificitet är beviset på att du var uppmärksam.", "**Gör frågan öppen.** En fråga som kan besvaras med \"ja\" eller \"nej\" brukar besvaras just så — och där dör samtalet.", "**Följ upp svaret.** Den starkaste signalen i forskningen var inte den första frågan utan den andra — den som visar att du lyssnade."] },
    { type: "p", text: "Men här är haken: i de flesta dejtingappar lämnas allt det här åt slumpen. Appen matchar er på foton, släpper ner er i en tom chattruta och hoppas att du på egen hand ska bli en skicklig frågeställare. Vetenskapen säger att frågor och turtagning bygger kontakt — och designen ger dig en tom skärm och ett \"hej\"." },
    { type: "h2", accent: "green", text: "Qulo bygger in frågan i den första kontakten" },
    { type: "p", text: "Qulos kärnmekanik börjar precis där forskningen pekar. För att matcha med någon på Qulo skickar du inte en kall öppningsreplik — du besvarar **2-10 frågor som personen själv har skrivit**. Din allra första kontakt är redan ett utbyte av riktiga frågor och riktiga svar om hur du tänker och vad du bryr dig om. Det pinsamma \"vad ska jag ens skriva?\"-ögonblicket är borta, för samtalet börjar mitt i substansen — inte vid \"hej\"." },
    { type: "p", text: "För att vara tydlig: ingen app kan lova att ett fantastiskt första utbyte blir en fantastisk relation — ingen ärlig läsning av forskningen stödjer det påståendet. Vad forskningen däremot stödjer är smalare och mer användbart: frågor, självutlämnande och turtagning är pålitliga sätt för främlingar att börja tycka om varandra. Qulo gör helt enkelt den dynamiken till startpunkten i stället för att lämna den åt turen." },
    { type: "quote", text: "Det bästa första meddelandet var aldrig \"hej\". Det var alltid en fråga — en som visar att du faktiskt tittade, och faktiskt bryr dig om svaret." },
    { type: "h2", accent: "green", text: "Slutsats" },
    { type: "p", text: "En halv miljon analyserade meddelanden säger att generiska hälsningar ignoreras. Harvards samtalsstudier säger att de som ställer frågor — särskilt följdfrågor — blir mer omtyckta och får fler andra dejter. Och experimentell psykologi säger att närhet faktiskt uppstår genom att turas om att fråga och svara. Om det är så kontakt börjar, varför lämna den åt en tom chattruta? Qulo inleder varje matchning med frågor värda att besvara. Ladda ner Qulo och börja ditt nästa samtal där vetenskapen säger att det ska börja." },
  ],
  hi: [
    { type: "p", text: "आपका मैच हो गया। आपने \"hey\" लिखा। और फिर… कुछ नहीं। अगर यह सिलसिला जाना-पहचाना लगता है, तो समस्या शायद आपमें नहीं — मैसेज में है। पहला मैसेज ऑनलाइन डेटिंग के सबसे ज़्यादा मापे गए पलों में से एक है, और लाखों बातचीतों का डेटा एक ही दिशा में इशारा करता है: सिर्फ़ अभिवादन नज़रअंदाज़ होते हैं, सवालों को जवाब मिलता है। इस फ़र्क़ के पीछे का मनोविज्ञान समझने लायक़ है, क्योंकि यह बदल देता है कि आप हर बातचीत कैसे शुरू करते हैं — ऐप पर हो या उसके बाहर।" },
    { type: "h2", text: "डेटा: हर ऐप पर \"Hey\" सबसे ख़राब ओपनर है" },
    { type: "p", text: "OkCupid की डेटा टीम ने प्लेटफ़ॉर्म पर 500,000 से ज़्यादा पहले मैसेजों का विश्लेषण किया और पाया कि सबसे आम ओपनर — \"hi\", \"hey\", \"hello\" — की जवाब दर औसत से काफ़ी नीचे थी, जबकि किसी ख़ास चीज़ से जुड़ने वाले मैसेजों ने कहीं बेहतर प्रदर्शन किया। सबसे जेनेरिक मैसेज ही सबसे बेअसर मैसेज निकला।" },
    { type: "p", text: "Hinge ने यही प्रयोग दूसरी तरफ़ से किया: 2015 में कंपनी ने एक महीने तक अपने यूज़र बेस पर लगभग 100 अलग-अलग ओपनिंग लाइनों का परीक्षण किया। नतीजा वही कहानी थी। क्लासिक \"hey, what's up?\" को हर बार उन ओपनर्स ने पीछे छोड़ दिया जो कोई व्यक्तिगत सवाल पूछते थे या कुछ ठोस प्रस्ताव रखते थे। नयापन, विशिष्टता और जवाब देने लायक़ एक असली सवाल — ये हर बार एक रूखे अभिवादन से बेहतर साबित हुए।" },
    { type: "h2", text: "Harvard की खोज: सवाल पूछने से लोग आपको पसंद करने लगते हैं" },
    { type: "p", text: "यह सिर्फ़ ऐप-डेटा की कोई अजीब बात नहीं है। 2017 में Karen Huang, Michael Yeomans, Alison Wood Brooks, Julia Minson और Francesca Gino ने Journal of Personality and Social Psychology में एक यादगार शीर्षक के साथ अध्ययनों की एक शृंखला प्रकाशित की: \"It Doesn't Hurt to Ask: Question-Asking Increases Liking\" (पूछने में कोई हर्ज नहीं: सवाल पूछने से पसंद बढ़ती है)। अजनबियों के बीच वास्तविक बातचीतों में, जो लोग ज़्यादा सवाल पूछते थे — ख़ासकर **फ़ॉलो-अप सवाल**, यानी वे सवाल जो सामने वाले की अभी-अभी कही बात पर आगे बढ़ते हैं — उन्हें उनके बातचीत के साथी लगातार ज़्यादा पसंद करते थे।" },
    { type: "p", text: "सबसे चौंकाने वाला हिस्सा असल ज़िंदगी से आया: शोधकर्ताओं ने वास्तविक स्पीड-डेटिंग बातचीतों का विश्लेषण किया — 110 डेटर, 2,000 से ज़्यादा डेट्स। जो स्पीड डेटर ज़्यादा फ़ॉलो-अप सवाल पूछते थे, उन्हें दूसरी डेट के लिए \"हाँ\" मिलने की संभावना ज़्यादा थी। सबसे ज़्यादा सवाल पूछने वाले शीर्ष एक-तिहाई लोगों को सबसे ज़्यादा दूसरी डेट के प्रस्ताव मिले। सवाल पूछना सिर्फ़ शिष्टाचार नहीं था; यह मापने योग्य रूप से आकर्षक था।" },
    { type: "h2", text: "यह क्यों काम करता है: एक अच्छा सवाल दोतरफ़ा तोहफ़ा है" },
    { type: "p", text: "शोधकर्ताओं ने जिस तंत्र की पहचान की, उसे **रिस्पॉन्सिवनेस** (संवेदनशील जवाबदेही) कहते हैं: जब आप किसी से एक असली सवाल पूछते हैं, तो आप संकेत देते हैं कि आप सुन रहे हैं, समझ रहे हैं और परवाह करते हैं। और जवाब देना वाक़ई अच्छा लगता है — मनोवैज्ञानिक लंबे समय से जानते हैं कि सेल्फ़-डिस्क्लोज़र, यानी किसी दिलचस्पी रखने वाले श्रोता से अपने बारे में बात करना, अपने आप में आनंददायक होता है। जवाब देने वाला व्यक्ति उस आनंद का श्रेय आपको, यानी सवाल पूछने वाले को देता है। एक अच्छा सवाल सामने वाले को यह एहसास दिलाता है कि वह दिलचस्प है — और इसी प्रक्रिया में आपको ज़्यादा पसंद किया जाने वाला बना देता है।" },
    { type: "p", text: "एक और तत्व है: बारी-बारी बात करना। Journal of Experimental Social Psychology में 2013 के एक अध्ययन में, Susan Sprecher और उनके सहयोगियों ने अजनबियों को दो तरीक़ों से मिलवाया — या तो बारी-बारी सवाल पूछकर और जवाब देकर, या ऐसे कि एक व्यक्ति अपने बारे में बताए और दूसरा सिर्फ़ सुने। बारी-बारी बात करने वालों ने काफ़ी ज़्यादा पसंद, क़रीबी, समानता का एहसास और आनंद महसूस किया। जुड़ाव किसी एक व्यक्ति के प्रदर्शन से नहीं आता; यह **अदल-बदल** से आता है — आप पूछें, मैं जवाब दूँ; मैं पूछूँ, आप जवाब दें।" },
    { type: "h2", text: "ऐसी बातचीत कैसे शुरू करें जिसे वाक़ई जवाब मिले" },
    { type: "p", text: "डेटा और मनोविज्ञान को साथ रखिए, और रणनीति ख़ुद-ब-ख़ुद लिख जाती है:" },
    { type: "ul", items: ["**रूखा अभिवादन छोड़ दें।** \"Hey\" सामने वाले को जवाब देने के लिए कुछ नहीं देता — यह सारी मेहनत उन्हीं पर डाल देता है।", "**किसी ख़ास चीज़ के बारे में पूछें।** उनकी शेयर की हुई किसी असली बात का ज़िक्र करें; विशिष्टता इस बात का सबूत है कि आपने ध्यान दिया।", "**सवाल को खुला रखें।** जिस सवाल का जवाब \"हाँ\" या \"नहीं\" में दिया जा सकता है, उसका जवाब अक्सर वैसा ही मिलता है — और बातचीत वहीं ख़त्म हो जाती है।", "**जवाब पर आगे सवाल पूछें।** शोध में सबसे मज़बूत संकेत पहला सवाल नहीं, दूसरा था — वह सवाल जो दिखाता है कि आपने सुना।"] },
    { type: "p", text: "पर यहाँ एक पेच है: ज़्यादातर डेटिंग ऐप्स पर यह सब क़िस्मत के भरोसे छोड़ दिया जाता है। ऐप आपको फ़ोटो के आधार पर मैच करता है, एक ख़ाली चैट बॉक्स में छोड़ देता है, और उम्मीद करता है कि आप किसी तरह ख़ुद ही सवाल पूछने में माहिर बन जाएँगे। विज्ञान कहता है कि सवाल और बारी-बारी बात करना जुड़ाव बनाते हैं — और डिज़ाइन आपको देता है एक ख़ाली स्क्रीन और एक \"hey\"।" },
    { type: "h2", accent: "green", text: "Qulo सवाल को पहले संपर्क में ही शामिल कर देता है" },
    { type: "p", text: "Qulo का मूल मैकेनिक ठीक वहीं से शुरू होता है जहाँ शोध इशारा करता है। Qulo पर किसी से मैच करने के लिए आप कोई ठंडा ओपनर नहीं भेजते — आप उस व्यक्ति के **ख़ुद लिखे 2-10 सवालों** के जवाब देते हैं। आपका पहला संपर्क ही असली सवालों और असली जवाबों का आदान-प्रदान होता है — इस बारे में कि आप कैसे सोचते हैं और किन चीज़ों की परवाह करते हैं। वह अजीब \"अब क्या लिखूँ?\" वाला पल ग़ायब हो जाता है, क्योंकि बातचीत \"hey\" से नहीं, सीधे मुद्दे की बात से शुरू होती है।" },
    { type: "p", text: "साफ़ कहें तो: कोई भी ऐप यह वादा नहीं कर सकता कि एक शानदार पहली बातचीत एक शानदार रिश्ते में बदलेगी — शोध की कोई भी ईमानदार व्याख्या इस दावे का समर्थन नहीं करती। शोध जो समर्थन करता है वह ज़्यादा सीमित और ज़्यादा उपयोगी है: सवाल, सेल्फ़-डिस्क्लोज़र और बारी-बारी बात करना — यही वे भरोसेमंद तरीक़े हैं जिनसे अजनबी एक-दूसरे को पसंद करने लगते हैं। Qulo बस इस गतिशीलता को क़िस्मत के भरोसे छोड़ने के बजाय शुरुआती बिंदु बना देता है।" },
    { type: "quote", text: "सबसे अच्छा पहला मैसेज कभी \"hey\" नहीं था। वह हमेशा एक सवाल था — ऐसा सवाल जो दिखाता है कि आपने वाक़ई ग़ौर किया, और जवाब की वाक़ई परवाह करते हैं।" },
    { type: "h2", accent: "green", text: "निष्कर्ष" },
    { type: "p", text: "विश्लेषण किए गए पाँच लाख मैसेज कहते हैं कि जेनेरिक अभिवादन नज़रअंदाज़ होते हैं। Harvard के बातचीत पर अध्ययन कहते हैं कि सवाल पूछने वाले — ख़ासकर फ़ॉलो-अप सवाल पूछने वाले — ज़्यादा पसंद किए जाते हैं और उन्हें ज़्यादा दूसरी डेट्स मिलती हैं। और प्रयोगात्मक मनोविज्ञान कहता है कि क़रीबी असल में बारी-बारी पूछने और जवाब देने से बनती है। अगर जुड़ाव ऐसे शुरू होता है, तो इसे एक ख़ाली चैट बॉक्स के भरोसे क्यों छोड़ें? Qulo हर मैच की शुरुआत ऐसे सवालों से करता है जिनके जवाब देने लायक़ हों। Qulo डाउनलोड करें और अपनी अगली बातचीत वहीं से शुरू करें जहाँ से विज्ञान कहता है कि होनी चाहिए।" },
  ],
};
